      },
    },
    metadata: {
      aliases: ["disclosure"],
      api: "compound-shorthand",
      taxonomy: "standard",
    },
  },
  subcomponents: {
    Item: Accordion.Item,
    ItemContent: Accordion.ItemContent,
    ItemTrigger: Accordion.ItemTrigger,
    Root: Accordion.Root,
