import {
  CheckCircleIcon,
  ChecksIcon,
  ClockCounterClockwiseIcon,
  MagicWandIcon,
  SparkleIcon,
  WarningIcon,
} from "@phosphor-icons/react";
import { Alert, Button } from "@pisagor/react";
import preview from "#/storybook/preview";

const meta = preview.meta({
  component: Alert,
  parameters: {
    docs: {
