import { useHotkey } from "@ark-ui/react";
import { appShellRecipe } from "@pisagor/recipes/app-shell";
import { type ComponentProps, useCallback, useMemo, useRef, useState } from "react";
import type {
  AppShellFixedStackVar,
  AppShellPlacement,
  AppShellRailState,
  AppShellRegionVar,
  AppShellSideState,
} from "./app-shell.context";
import {
  APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS,
  APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS,
  AppShellContext,
  ZERO_FIXED_STACK_VARS,
  ZERO_REGION_VARS,
} from "./app-shell.context";
import { type AppShellSlots, partitionAppShellChildren } from "./slots";

const APP_SHELL_GRID_COLUMNS = `
  var(--app-shell-start-inspector-width, 0px)
  var(--app-shell-start-rail-width, 0px)
  var(--app-shell-start-panel-width, 0px)
  minmax(0, 1fr)
  var(--app-shell-end-panel-width, 0px)
  var(--app-shell-end-rail-width, 0px)
  var(--app-shell-end-inspector-width, 0px)
`;

const APP_SHELL_CONTENT_ROW =
  '"start-inspector start-rail start-panel main end-panel end-rail end-inspector"';

const APP_SHELL_NAV_ROW =
  '"start-inspector navigation navigation navigation navigation navigation end-inspector"';

const APP_SHELL_BANNER_ROW = '"banner banner banner banner banner banner banner"';

function buildGridAreas(hasBanner: boolean, hasNavigation: boolean) {
  if (hasBanner && hasNavigation) {
    return `${APP_SHELL_BANNER_ROW}\n${APP_SHELL_NAV_ROW}\n${APP_SHELL_CONTENT_ROW}`;
  }

  if (hasBanner) {
    return `${APP_SHELL_BANNER_ROW}\n${APP_SHELL_CONTENT_ROW}`;
  }

  if (hasNavigation) {
    return `${APP_SHELL_NAV_ROW}\n${APP_SHELL_CONTENT_ROW}`;
  }

  return APP_SHELL_CONTENT_ROW;
}

function buildGridRows(hasBanner: boolean, hasNavigation: boolean) {
  return [...(hasBanner ? ["auto"] : []), ...(hasNavigation ? ["auto"] : []), "auto"].join(" ");
}

export interface AppShellRootProps extends ComponentProps<"div"> {
  /**
   * Style recipe. Defaults to `appShellRecipe` from `@pisagor/recipes/app-shell`.
   *
   * @defaultValue appShellRecipe
   */
  recipe?: typeof appShellRecipe;
}

function useShellGridStyle(childSlots: AppShellSlots) {
  const hasBanner = Boolean(childSlots.banner);
  const hasNavigation = Boolean(childSlots.navigation);

  return useMemo(
    () => ({
      gridTemplateAreas: buildGridAreas(hasBanner, hasNavigation),
      gridTemplateColumns: APP_SHELL_GRID_COLUMNS,
      gridTemplateRows: buildGridRows(hasBanner, hasNavigation),
    }),
    [hasBanner, hasNavigation],
  );
}

export function AppShellRoot({
  children,
  recipe = appShellRecipe,
  className,
  style,
  ...rest
}: AppShellRootProps) {
  const childSlots = useMemo(() => partitionAppShellChildren(children), [children]);
  const slots = recipe();
  const [regionRevision, setRegionRevision] = useState(0);
  const [regionVars, setRegionVars] = useState(ZERO_REGION_VARS);
  const [fixedStackVars, setFixedStackVars] = useState(ZERO_FIXED_STACK_VARS);
  const panelStates = useRef<Partial<Record<AppShellPlacement, AppShellSideState>>>({});
  const inspectorStates = useRef<Partial<Record<AppShellPlacement, AppShellSideState>>>({});
  const railStates = useRef<Partial<Record<AppShellPlacement, AppShellRailState>>>({});
  const shellRef = useRef<HTMLDivElement>(null);
  const [regionResizing, setRegionResizing] = useState(false);
  const gridStyle = useShellGridStyle(childSlots);

  const setRegionVar = useCallback((name: AppShellRegionVar, value: string) => {
    setRegionVars((current) => {
      if (current[name] === value) {
        return current;
      }
      return { ...current, [name]: value };
    });
  }, []);

  const setFixedStackVar = useCallback((name: AppShellFixedStackVar, value: string) => {
    setFixedStackVars((current) => {
      if (current[name] === value) {
        return current;
      }
      return { ...current, [name]: value };
    });
  }, []);

  useHotkey({
    action: () => {
      panelStates.current.start?.toggle();
    },
    hotkey: "mod+\\",
  });

  const notifyRegionChange = useCallback(() => {
    setRegionRevision((revision) => revision + 1);
  }, []);

  const contextValue = useMemo(
    () => ({
      defaultInspectorResizableProps: APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS,
      defaultPanelResizableProps: APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS,
      fixedStackVars,
      inspectorStates,
      notifyRegionChange,
      panelStates,
      railStates,
      regionResizing,
      regionRevision,
      regionVars,
      setFixedStackVar,
      setRegionResizing,
      setRegionVar,
      shellRef,
      slots,
    }),
    [
      fixedStackVars,
      notifyRegionChange,
      regionResizing,
      regionRevision,
      regionVars,
      setFixedStackVar,
      setRegionVar,
      slots,
    ],
  );

  const shellStyle = useMemo(
    () => ({
      ...regionVars,
      ...fixedStackVars,
    }),
    [fixedStackVars, regionVars],
  );

  return (
    <AppShellContext value={contextValue}>
      <div
        {...rest}
        className={slots.base({ className })}
        data-part="root"
        data-resizing={regionResizing ? "" : undefined}
        data-scope="app-shell"
        ref={shellRef}
        style={{ ...shellStyle, ...gridStyle, ...style }}
      >
        {childSlots.banner}
        {childSlots.inspectors.start}
        {childSlots.navigation}
        {childSlots.inspectors.end}
        {childSlots.rails.start}
        {childSlots.panels.start}
        {childSlots.main}
        {childSlots.panels.end}
        {childSlots.rails.end}
      </div>
    </AppShellContext>
  );
}

// #region Display Names
AppShellRoot.displayName = "AppShell";
// #endregion

import { useUncontrolled } from "@mantine/hooks";
import type { AppShellRecipe } from "@pisagor/recipes/app-shell";
import { type RefObject, useCallback } from "react";
import { createContext } from "../../utils";

export type AppShellPlacement = "start" | "end";

/** How a shell region behaves when the page scrolls. */
export type AppShellRegionPosition = "fixed" | "relative";

/** Vertical placement of the visible resize-handle grip. */
export type AppShellResizeHandlePosition = "bottom" | "center" | "top";

/** Resizable edge-handle options for a single panel or inspector region. */
export interface AppShellResizableProps {
  /**
   * Whether the region shows a resize handle when open.
   *
   * @defaultValue true
   */
  enabled?: boolean;
  /**
   * Vertical placement of the visible resize-handle grip.
   *
   * @defaultValue `"top"` via `useAppShell()`, `"center"` on the handle component
   */
  handlePosition?: AppShellResizeHandlePosition;
}

export const APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS = {
  enabled: true,
  handlePosition: "top",
} as const satisfies Required<Pick<AppShellResizableProps, "enabled" | "handlePosition">>;

export const APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS = {
  enabled: true,
  handlePosition: "top",
} as const satisfies Required<Pick<AppShellResizableProps, "enabled" | "handlePosition">>;

export type AppShellFixedStackVar = "--app-shell-banner-height" | "--app-shell-navigation-height";

export type AppShellRegionVar =
  | "--app-shell-end-inspector-width"
  | "--app-shell-end-panel-width"
  | "--app-shell-end-rail-width"
  | "--app-shell-start-inspector-width"
  | "--app-shell-start-panel-width"
  | "--app-shell-start-rail-width";

export interface AppShellSideState {
  open: boolean;
  setOpen: (open: boolean | ((current: boolean) => boolean)) => void;
  toggle: () => void;
}

export interface AppShellRailState {
  activeRailId?: string;
  placement: AppShellPlacement;
  setActiveRailId: (id: string) => void;
}

interface AppShellContextValue {
  inspectorStates: RefObject<Partial<Record<AppShellPlacement, AppShellSideState>>>;
  notifyRegionChange: () => void;
  panelStates: RefObject<Partial<Record<AppShellPlacement, AppShellSideState>>>;
  railStates: RefObject<Partial<Record<AppShellPlacement, AppShellRailState>>>;
  regionResizing: boolean;
  regionRevision: number;
  regionVars: Record<AppShellRegionVar, string>;
  fixedStackVars: Record<AppShellFixedStackVar, string>;
  defaultInspectorResizableProps: typeof APP_SHELL_DEFAULT_INSPECTOR_RESIZABLE_PROPS;
  defaultPanelResizableProps: typeof APP_SHELL_DEFAULT_PANEL_RESIZABLE_PROPS;
  setRegionResizing: (resizing: boolean) => void;
  setFixedStackVar: (name: AppShellFixedStackVar, value: string) => void;
  setRegionVar: (name: AppShellRegionVar, value: string) => void;
  shellRef: RefObject<HTMLDivElement | null>;
  /** Slot class recipes from `appShellRecipe`. */
  slots: AppShellRecipe;
}

interface UseSideStateOptions {
  controlledOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export const ZERO_FIXED_STACK_VARS: Record<AppShellFixedStackVar, string> = {
  "--app-shell-banner-height": "0px",
  "--app-shell-navigation-height": "0px",
};

export const ZERO_REGION_VARS: Record<AppShellRegionVar, string> = {
  "--app-shell-end-inspector-width": "0px",
  "--app-shell-end-panel-width": "0px",
  "--app-shell-end-rail-width": "0px",
  "--app-shell-start-inspector-width": "0px",
  "--app-shell-start-panel-width": "0px",
  "--app-shell-start-rail-width": "0px",
};

export const { AppShellContext, useAppShell } = createContext<AppShellContextValue>()({
  name: "AppShell",
});

export function useSideState({
  defaultOpen = false,
  controlledOpen,
  onOpenChange,
}: UseSideStateOptions): AppShellSideState {
  const [open, setOpenValue] = useUncontrolled({
    defaultValue: defaultOpen,
    finalValue: false,
    onChange: onOpenChange,
    value: controlledOpen,
  });

  const setOpen = useCallback(
    (value: boolean | ((current: boolean) => boolean)) => {
      setOpenValue(typeof value === "function" ? value(open) : value);
    },
    [open, setOpenValue],
  );

  const toggle = useCallback(() => {
    setOpenValue(!open);
  }, [open, setOpenValue]);

  return { open, setOpen, toggle };
}

import { AppShellRoot } from "./app-shell";
