import { ark } from "@ark-ui/react/factory";
import {
  type TabListProps,
  Tabs as TabsPrimitive,
  type TabsRootProps,
  type TabTriggerProps,
} from "@ark-ui/react/tabs";
import {
  bottomNavigationItemRecipe,
  bottomNavigationRecipe,
} from "@pisagor/recipes/bottom-navigation";
import type { ComponentProps } from "react";
import {
  BottomNavigationContext,
  BottomNavigationItemContext,
  useBottomNavigation,
  useBottomNavigationItem,
} from "./bottom-navigation.context";

// #region Types
export interface BottomNavigationRootProps extends TabsRootProps {
  /**
   * Style recipe. Defaults to `bottomNavigationRecipe` from `@pisagor/recipes/bottom-navigation`.
   *
   * @defaultValue bottomNavigationRecipe
   */
  recipe?: typeof bottomNavigationRecipe;
}

export type BottomNavigationProps = BottomNavigationRootProps;

export type BottomNavigationListProps = TabListProps;

export interface BottomNavigationItemProps extends TabTriggerProps {
  /**
   * Style recipe. Defaults to `bottomNavigationItemRecipe` from `@pisagor/recipes/bottom-navigation`.
   *
   * @defaultValue bottomNavigationItemRecipe
   */
  itemRecipe?: typeof bottomNavigationItemRecipe;
}

export type BottomNavigationItemIconProps = ComponentProps<typeof ark.span>;

export type BottomNavigationItemLabelProps = ComponentProps<typeof ark.span>;
// #endregion

// #region Parts
export function BottomNavigationRoot({
  recipe = bottomNavigationRecipe,
  className,
  ...rest
}: BottomNavigationRootProps) {
  const slots = recipe();

  return (
    <BottomNavigationContext value={{ slots }}>
      <TabsPrimitive.Root {...rest} className={slots.base({ className })} />
    </BottomNavigationContext>
  );
}

export function BottomNavigationList({ className, ...rest }: BottomNavigationListProps) {
  const { slots } = useBottomNavigation();

  return <TabsPrimitive.List {...rest} className={slots.list({ className })} />;
}

export function BottomNavigationItem({
  children,
  itemRecipe = bottomNavigationItemRecipe,
  className,
  ...rest
}: BottomNavigationItemProps) {
  const slots = itemRecipe();

  return (
    <BottomNavigationItemContext value={{ slots }}>
      <TabsPrimitive.Trigger {...rest} className={slots.base({ className })}>
        {children}
      </TabsPrimitive.Trigger>
    </BottomNavigationItemContext>
  );
}

export function BottomNavigationItemIcon({ className, ...rest }: BottomNavigationItemIconProps) {
  const { slots } = useBottomNavigationItem();

  return (
    <ark.span
      {...rest}
      aria-hidden
      className={slots.icon({ className })}
      data-part="item-icon"
      data-scope="bottom-navigation"
    />
  );
}

export function BottomNavigationItemLabel({ className, ...rest }: BottomNavigationItemLabelProps) {
  const { slots } = useBottomNavigationItem();

  return (
    <ark.span
      {...rest}
      className={slots.label({ className })}
      data-part="item-label"
      data-scope="bottom-navigation"
    />
  );
}
// #endregion

// #region Display Names
BottomNavigationRoot.displayName = "BottomNavigation";
BottomNavigationList.displayName = "BottomNavigation.List";
BottomNavigationItem.displayName = "BottomNavigation.Item";
BottomNavigationItemIcon.displayName = "BottomNavigation.ItemIcon";
BottomNavigationItemLabel.displayName = "BottomNavigation.ItemLabel";
// #endregion

import type {
  BottomNavigationItemRecipe,
  BottomNavigationRecipe,
} from "@pisagor/recipes/bottom-navigation";
import { createContext } from "../../utils";

interface BottomNavigationContextValue {
  slots: BottomNavigationRecipe;
}

interface BottomNavigationItemContextValue {
  slots: BottomNavigationItemRecipe;
}

export const { BottomNavigationContext, useBottomNavigation } =
  createContext<BottomNavigationContextValue>()({
    name: "BottomNavigation",
  });

export const { BottomNavigationItemContext, useBottomNavigationItem } =
  createContext<BottomNavigationItemContextValue>()({
    name: "BottomNavigationItem",
  });

import {
  BottomNavigationItem,
  BottomNavigationItemIcon,
  BottomNavigationItemLabel,
  BottomNavigationList,
  BottomNavigationRoot,
} from "./bottom-navigation";

export type {
  BottomNavigationItemIconProps,
  BottomNavigationItemLabelProps,
  BottomNavigationItemProps,
  BottomNavigationListProps,
  BottomNavigationProps,
  BottomNavigationRootProps,
} from "./bottom-navigation";

export const BottomNavigation = Object.assign(BottomNavigationRoot, {
  Item: BottomNavigationItem,
  ItemIcon: BottomNavigationItemIcon,
  ItemLabel: BottomNavigationItemLabel,
  List: BottomNavigationList,
});

import { ark } from "@ark-ui/react/factory";
import { CaretRightIcon, DotsThreeIcon } from "@phosphor-icons/react";
import { breadcrumbItemRecipe, breadcrumbRecipe } from "@pisagor/recipes/breadcrumb";
import type { ComponentProps, ReactNode } from "react";
import { Fragment } from "react";
import {
  BreadcrumbContext,
  BreadcrumbItemContext,
  useBreadcrumb,
  useBreadcrumbItem,
} from "./breadcrumb.context";

// #region Types
interface BreadcrumbPresetItem {
  label: ReactNode;
  href?: string;
  isCurrentPage?: boolean;
}

export type BreadcrumbListProps = ComponentProps<typeof ark.ol>;
export interface BreadcrumbItemProps extends ComponentProps<typeof ark.li> {
  /**
   * Style recipe. Defaults to `breadcrumbItemRecipe` from `@pisagor/recipes/breadcrumb`.
   *
   * @defaultValue breadcrumbItemRecipe
   */
  itemRecipe?: typeof breadcrumbItemRecipe;
}
export type BreadcrumbLinkProps = ComponentProps<typeof ark.a>;
export type BreadcrumbPageProps = ComponentProps<typeof ark.span>;
export type BreadcrumbSeparatorProps = ComponentProps<typeof ark.li>;
export type BreadcrumbEllipsisProps = ComponentProps<typeof ark.span>;

export interface BreadcrumbRootProps extends ComponentProps<typeof ark.nav> {
  /**
   * Accessible label for the breadcrumb navigation landmark.
   *
   * @defaultValue "Breadcrumb"
   */
  "aria-label"?: string;
  /**
   * Style recipe. Defaults to `breadcrumbRecipe` from `@pisagor/recipes/breadcrumb`.
   *
   * @defaultValue breadcrumbRecipe
   */
  recipe?: typeof breadcrumbRecipe;
}

export interface BreadcrumbProps extends Omit<BreadcrumbRootProps, "children"> {
  items?: BreadcrumbPresetItem[];
}
// #endregion

// #region Parts
export function BreadcrumbRoot({
  "aria-label": ariaLabel = "Breadcrumb",
  children,
  recipe = breadcrumbRecipe,
  ...rest
}: BreadcrumbRootProps) {
  const slots = recipe();

  return (
    <BreadcrumbContext value={{ slots }}>
      <ark.nav {...rest} aria-label={ariaLabel} data-part="root" data-scope="breadcrumb">
        {children}
      </ark.nav>
    </BreadcrumbContext>
  );
}

export function BreadcrumbList({ className, ...rest }: BreadcrumbListProps) {
  const { slots } = useBreadcrumb();

  return (
    <ark.ol
      {...rest}
      className={slots.list({ className })}
      data-part="list"
      data-scope="breadcrumb"
      role="list"
    />
  );
}

export function BreadcrumbItem({
  children,
  itemRecipe = breadcrumbItemRecipe,
  className,
  ...rest
}: BreadcrumbItemProps) {
  const slots = itemRecipe();

  return (
    <BreadcrumbItemContext value={{ slots }}>
      <ark.li
        {...rest}
        className={slots.base({ className })}
        data-part="item"
        data-scope="breadcrumb"
      >
        {children}
      </ark.li>
    </BreadcrumbItemContext>
  );
}

export function BreadcrumbLink({ className, ...rest }: BreadcrumbLinkProps) {
  const { slots } = useBreadcrumbItem();

  return (
    <ark.a
      {...rest}
      className={slots.link({ className })}
      data-part="link"
      data-scope="breadcrumb"
    />
  );
}

export function BreadcrumbPage({ className, ...rest }: BreadcrumbPageProps) {
  const { slots } = useBreadcrumbItem();

  return (
    <ark.span
      {...rest}
      aria-current="page"
      className={slots.page({ className })}
      data-part="page"
      data-scope="breadcrumb"
    />
  );
}

export function BreadcrumbSeparator({ children, className, ...rest }: BreadcrumbSeparatorProps) {
  const { slots } = useBreadcrumb();

  return (
    <ark.li
      {...rest}
      aria-hidden="true"
      className={slots.separator({ className })}
      data-part="separator"
      data-scope="breadcrumb"
      role="presentation"
    >
      {children ?? <CaretRightIcon />}
    </ark.li>
  );
}

export function BreadcrumbEllipsis(props: BreadcrumbEllipsisProps) {
  const { slots } = useBreadcrumb();

  return (
    <ark.span
      {...props}
      aria-hidden="true"
      data-part="ellipsis"
      data-scope="breadcrumb"
      role="presentation"
    >
      <DotsThreeIcon className={slots.ellipsis()} />
    </ark.span>
  );
}
// #endregion

// #region Shorthand
export function BreadcrumbShorthand({ items, ...rest }: BreadcrumbProps) {
  return (
    <BreadcrumbRoot {...rest}>
      {items && (
        <BreadcrumbList>
          {items.map((item, index) => (
            <Fragment key={item.href ?? String(item.label)}>
              {index > 0 && <BreadcrumbSeparator />}
              <BreadcrumbItem>
                {item.isCurrentPage ? (
                  <BreadcrumbPage>{item.label}</BreadcrumbPage>
                ) : item.href ? (
                  <BreadcrumbLink href={item.href}>{item.label}</BreadcrumbLink>
                ) : (
                  item.label
                )}
              </BreadcrumbItem>
            </Fragment>
          ))}
        </BreadcrumbList>
      )}
    </BreadcrumbRoot>
  );
}
// #endregion

// #region Display Names
BreadcrumbRoot.displayName = "Breadcrumb.Root";
BreadcrumbList.displayName = "Breadcrumb.List";
BreadcrumbItem.displayName = "Breadcrumb.Item";
BreadcrumbLink.displayName = "Breadcrumb.Link";
BreadcrumbPage.displayName = "Breadcrumb.Page";
BreadcrumbSeparator.displayName = "Breadcrumb.Separator";
BreadcrumbEllipsis.displayName = "Breadcrumb.Ellipsis";
BreadcrumbShorthand.displayName = "Breadcrumb";
// #endregion

import type { BreadcrumbItemRecipe, BreadcrumbRecipe } from "@pisagor/recipes/breadcrumb";
import { createContext } from "../../utils";

interface BreadcrumbContextValue {
  slots: BreadcrumbRecipe;
}

interface BreadcrumbItemContextValue {
  slots: BreadcrumbItemRecipe;
}

export const { BreadcrumbContext, useBreadcrumb } = createContext<BreadcrumbContextValue>()({
  name: "Breadcrumb",
});

export const { BreadcrumbItemContext, useBreadcrumbItem } =
  createContext<BreadcrumbItemContextValue>()({
    name: "BreadcrumbItem",
  });

import {
  BreadcrumbEllipsis,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbRoot,
  BreadcrumbSeparator,
  BreadcrumbShorthand,
} from "./breadcrumb";

export type {
  BreadcrumbEllipsisProps,
  BreadcrumbItemProps,
  BreadcrumbLinkProps,
  BreadcrumbListProps,
  BreadcrumbPageProps,
  BreadcrumbProps,
  BreadcrumbRootProps,
  BreadcrumbSeparatorProps,
} from "./breadcrumb";

export const Breadcrumb = Object.assign(BreadcrumbShorthand, {
  Ellipsis: BreadcrumbEllipsis,
  Item: BreadcrumbItem,
  Link: BreadcrumbLink,
  List: BreadcrumbList,
  Page: BreadcrumbPage,
  Root: BreadcrumbRoot,
  Separator: BreadcrumbSeparator,
});

import { ark } from "@ark-ui/react/factory";
import { type ButtonVariantProps, buttonRecipe } from "@pisagor/recipes/button";
import type { ComponentProps } from "react";
import { Spinner } from "../spinner";

// #region Types
export interface ButtonProps extends ComponentProps<typeof ark.button>, ButtonVariantProps {
  /**
   * Style recipe. Defaults to `buttonRecipe` from `@pisagor/recipes/button`.
   *
   * @defaultValue buttonRecipe
   */
  recipe?: typeof buttonRecipe;
}
// #endregion

// #region Component
export function Button({
  clickEffect = true,
  loading = false,
  pill = false,
  size = "md",
  variant = "default",
  disabled,
  type = "button",
  children,
  recipe = buttonRecipe,
  className,
  ...rest
}: ButtonProps) {
  const slots = recipe({ clickEffect, loading, pill, size, variant });

  return (
    <ark.button
      {...rest}
      aria-busy={loading || undefined}
      className={slots.base({ className })}
      data-part="root"
      data-scope="button"
      data-size={size}
      data-state={loading ? "loading" : "idle"}
      data-variant={variant}
      disabled={disabled || loading}
      type={type}
    >
      {loading ? (
        <>
          <span aria-hidden className={slots.hidden()}>
            {children}
          </span>
          <span className={slots.srOnly()}>{children}</span>
          <span className={slots.spinner()}>
            <Spinner aria-hidden />
          </span>
        </>
      ) : (
        children
      )}
    </ark.button>
  );
}
// #endregion

