import type {
  CollapsibleContentProps,
  CollapsibleIndicatorProps,
  CollapsibleRootProps as CollapsiblePrimitiveRootProps,
  CollapsibleTriggerProps,
} from "@ark-ui/react/collapsible";
import { Collapsible as CollapsiblePrimitive } from "@ark-ui/react/collapsible";
import { CaretDownIcon } from "@phosphor-icons/react";
import { collapsibleRecipe } from "@pisagor/recipes/collapsible";

import { CollapsibleContext, useCollapsible } from "./collapsible.context";

// #region Types
export interface CollapsibleRootProps extends CollapsiblePrimitiveRootProps {
  /**
   * Style recipe. Defaults to `collapsibleRecipe` from `@pisagor/recipes/collapsible`.
   *
   * @defaultValue collapsibleRecipe
   */
  recipe?: typeof collapsibleRecipe;
}
// #endregion

// #region Parts
export function CollapsibleRoot({
  lazyMount,
  unmountOnExit,
  children,
  collapsedHeight,
  recipe = collapsibleRecipe,
  className,
  ...rest
}: CollapsibleRootProps) {
  const slots = recipe();

  return (
    <CollapsibleContext value={{ slots }}>
      <CollapsiblePrimitive.Root
        {...rest}
        className={slots.base({ className })}
        collapsedHeight={collapsedHeight}
        data-partial-collapse={collapsedHeight ? "" : undefined}
        lazyMount={collapsedHeight ? false : lazyMount}
        unmountOnExit={collapsedHeight ? false : unmountOnExit}
      >
        {children}
      </CollapsiblePrimitive.Root>
    </CollapsibleContext>
  );
}

export function CollapsibleTrigger({ className, ...rest }: CollapsibleTriggerProps) {
  const { slots } = useCollapsible();

  return <CollapsiblePrimitive.Trigger {...rest} className={slots.trigger({ className })} />;
}

export function CollapsibleContent({ children, className, ...rest }: CollapsibleContentProps) {
  const { slots } = useCollapsible();

  return (
    <CollapsiblePrimitive.Content {...rest} className={slots.content()}>
      <div className={className}>{children}</div>
    </CollapsiblePrimitive.Content>
  );
}

export function CollapsibleIndicator({ className, ...rest }: CollapsibleIndicatorProps) {
  const { slots } = useCollapsible();

  return (
    <CollapsiblePrimitive.Indicator {...rest} className={slots.indicator({ className })}>
      <CaretDownIcon className={slots.icon()} />
    </CollapsiblePrimitive.Indicator>
  );
}
// #endregion

// #region Display Names
CollapsibleRoot.displayName = "Collapsible";
CollapsibleTrigger.displayName = "Collapsible.Trigger";
CollapsibleContent.displayName = "Collapsible.Content";
CollapsibleIndicator.displayName = "Collapsible.Indicator";
// #endregion

import type { CollapsibleRecipe } from "@pisagor/recipes/collapsible";
import { createContext } from "../../utils";

interface CollapsibleContextValue {
  slots: CollapsibleRecipe;
}

export const { CollapsibleContext, useCollapsible } = createContext<CollapsibleContextValue>()({
  name: "Collapsible",
});

import {
  CollapsibleContent,
  CollapsibleIndicator,
  CollapsibleRoot,
  CollapsibleTrigger,
} from "./collapsible";

export type {
  CollapsibleContentProps,
  CollapsibleIndicatorProps,
  CollapsibleRootProps,
  CollapsibleTriggerProps,
} from "@ark-ui/react/collapsible";

export const Collapsible = Object.assign(CollapsibleRoot, {
  Content: CollapsibleContent,
  Indicator: CollapsibleIndicator,
  Trigger: CollapsibleTrigger,
});

import type {
  ColorPickerAreaThumbProps,
  ColorPickerChannelInputProps,
  ColorPickerContentProps,
  ColorPickerAreaProps as ColorPickerPrimitiveAreaProps,
  ColorPickerControlProps as ColorPickerPrimitiveControlProps,
  ColorPickerRootProps as ColorPickerPrimitiveRootProps,
  ColorPickerSwatchGroupProps,
  ColorPickerSwatchProps,
  ColorPickerTriggerProps,
  ColorPickerValueChangeDetails,
  ColorPickerValueSwatchProps,
  ColorPickerValueTextProps,
  ColorPickerViewProps,
} from "@ark-ui/react/color-picker";
import {
  ColorPicker as ColorPickerPrimitive,
  parseColor as parseColorArk,
  useColorPickerContext,
} from "@ark-ui/react/color-picker";
import { ark } from "@ark-ui/react/factory";
import { Portal } from "@ark-ui/react/portal";
import { useUncontrolled } from "@mantine/hooks";
import { CheckIcon, EyedropperIcon, XIcon } from "@phosphor-icons/react";
import { colorPickerRecipe } from "@pisagor/recipes/color-picker";
import { cn } from "@pisagor/utils";
import { type ComponentProps, useMemo } from "react";
import { Button, type ButtonProps } from "../button";
import { InputGroup, type InputGroupButtonProps } from "../input-group";
import { ColorPickerSlotsContext, useColorPicker } from "./color-picker.context";

// #region Types
type FormControlVariant = "primary" | "secondary";

export type ColorPickerRootProps = Omit<
  ColorPickerPrimitiveRootProps,
  "defaultValue" | "value" | "onValueChange"
>;

export interface ColorPickerProps extends ColorPickerRootProps {
  /** Visual shell variant for preset field input. When omitted, resolves from `Surface`. */
  variant?: FormControlVariant;
  /**
   * Whether to show a clear button when a color is selected.
   *
   * @defaultValue false
   */
  clearable?: boolean;
  /**
   * The default value of the color picker when uncontrolled.
   *
   * @remarks
   * Ignored when `value` is set.
   */
  defaultValue?: string;
  /**
   * The controlled color value.
   *
   * @remarks
   * When set, `defaultValue` is ignored. Pair with `onValueChange` to handle updates.
   */
  value?: string;
  /** Called with the hex color string when the value changes. */
  onValueChange?: (value: string) => void;
  /**
   * Style recipe. Defaults to `colorPickerRecipe` from `@pisagor/recipes/color-picker`.
   *
   * @defaultValue colorPickerRecipe
   */
  recipe?: typeof colorPickerRecipe;
}

export interface ColorPickerClearTriggerProps extends InputGroupButtonProps {
  /**
   * Whether to show the clear button.
   *
   * @defaultValue false
   */
  clearable?: boolean;
}

export interface ColorPickerControlProps extends ColorPickerPrimitiveControlProps {
  /**
   * Whether to show a clear button when a color is selected.
   *
   * @defaultValue false
   */
  clearable?: boolean;
}

export type ColorPickerEyeDropperTriggerProps = ComponentProps<
  typeof ColorPickerPrimitive.EyeDropperTrigger
> &
  ButtonProps;

export interface ColorPickerAreaProps extends ColorPickerPrimitiveAreaProps {
  /**
   *
   */
  showDots?: boolean;
}

export type ColorPickerTransparencyGridProps = ComponentProps<
  typeof ColorPickerPrimitive.TransparencyGrid
>;

export type ColorPickerChannelSliderProps = ComponentProps<
  typeof ColorPickerPrimitive.ChannelSlider
>;

export type ColorPickerSwatchTriggerProps = ComponentProps<
  typeof ColorPickerPrimitive.SwatchTrigger
>;

export type ColorPickerSwatchIndicatorProps = ComponentProps<
  typeof ColorPickerPrimitive.SwatchIndicator
>;

export type ColorPickerInputProps = Partial<ColorPickerChannelInputProps>;

export type ColorPickerSwatchPreviewProps = ComponentProps<typeof ark.div>;
// #endregion

// #region Parts
/**
 * Parses a color string into an Ark UI color object.
 *
 * @returns A parsed color value for use with ColorPicker APIs.
 */
export const parseColor = parseColorArk;

export function ColorPickerRoot({
  variant,
  defaultValue,
  positioning = {
    placement: "top-start",
  },
  value,
  children,
  onValueChange,
  recipe = colorPickerRecipe,
  className,
  ...rest
}: ColorPickerProps) {
  const slots = recipe();
  const [color, setColor, isControlled] = useUncontrolled({
    defaultValue,
    onChange: onValueChange,
    value,
  });

  const parsedColor = useMemo(() => {
    return color ? parseColor(color) : undefined;
  }, [color]);

  const handleValueChange = (e: ColorPickerValueChangeDetails) => {
    setColor(e.valueAsString);
  };

  return (
    <ColorPickerSlotsContext value={{ slots }}>
      <ColorPickerPrimitive.Root
        {...rest}
        className={slots.base({ className })}
        defaultValue={!isControlled ? parsedColor : undefined}
        onValueChange={handleValueChange}
        positioning={positioning}
        value={isControlled ? parsedColor : undefined}
      >
        {children}

        <ColorPickerPrimitive.HiddenInput />
      </ColorPickerPrimitive.Root>
    </ColorPickerSlotsContext>
  );
}

export function ColorPickerClearTrigger({
  clearable = false,
  onClick,
  className,
  ...rest
}: ColorPickerClearTriggerProps) {
  const api = useColorPickerContext();

  if (!clearable) {
    return null;
  }

  const controlProps = api.getControlProps() as { disabled?: boolean; readOnly?: boolean };
  if (controlProps.disabled || controlProps.readOnly) {
    return null;
  }

  const isCleared = api.value.getChannelValue("alpha") === 0;
  if (isCleared) {
    return null;
  }

  return (
    <InputGroup.Addon align="inline-end">
      <InputGroup.Button
        {...rest}
        aria-label="Clear color"
        className={className}
        data-part="clear-trigger"
        data-scope="color-picker"
        onClick={(event) => {
          api.setValue(parseColor("rgba(0, 0, 0, 0)"));
          onClick?.(event);
        }}
        size="icon-xs"
        type="button"
        variant="ghost"
      >
        <XIcon />
      </InputGroup.Button>
    </InputGroup.Addon>
  );
}

export function ColorPickerControl({
  clearable = false,
  children,
  className,
  ...rest
}: ColorPickerControlProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.Control {...rest} className={slots.control({ className })}>
      {children}
      {clearable ? <ColorPickerClearTrigger /> : null}
    </ColorPickerPrimitive.Control>
  );
}

export function ColorPickerTrigger(props: ColorPickerTriggerProps) {
  return <ColorPickerPrimitive.Trigger {...props} />;
}

export function ColorPickerTransparencyGrid({
  className,
  ...rest
}: ColorPickerTransparencyGridProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.TransparencyGrid
      {...rest}
      className={slots.transparencyGrid({ className })}
    />
  );
}

export function ColorPickerContent({ className, ...rest }: ColorPickerContentProps) {
  const { slots } = useColorPicker();

  return (
    <Portal>
      <ColorPickerPrimitive.Positioner>
        <ColorPickerPrimitive.Content {...rest} className={slots.content({ className })} />
      </ColorPickerPrimitive.Positioner>
    </Portal>
  );
}

export function ColorPickerView({ className, ...rest }: ColorPickerViewProps) {
  const { slots } = useColorPicker();

  return <ColorPickerPrimitive.View {...rest} className={slots.view({ className })} />;
}

export function ColorPickerChannelSlider({
  children,
  className,
  ...rest
}: ColorPickerChannelSliderProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.ChannelSlider {...rest} className={slots.channelSlider({ className })}>
      {children}

      <ColorPickerPrimitive.ChannelSliderTrack className={slots.channelSliderTrack()} />
      <ColorPickerPrimitive.ChannelSliderThumb className={slots.channelSliderThumb()} />
    </ColorPickerPrimitive.ChannelSlider>
  );
}

export function ColorPickerEyeDropperTrigger({
  size = "icon-md",
  variant = "outline",
  children,
  ...rest
}: ColorPickerEyeDropperTriggerProps) {
  return (
    <ColorPickerPrimitive.EyeDropperTrigger {...rest} asChild>
      <Button size={size} variant={variant}>
        {children || <EyedropperIcon />}
      </Button>
    </ColorPickerPrimitive.EyeDropperTrigger>
  );
}

export function ColorPickerSwatchGroup({ className, ...rest }: ColorPickerSwatchGroupProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.SwatchGroup {...rest} className={slots.swatchGroup({ className })} />
  );
}

export function ColorPickerSwatchTrigger({ className, ...rest }: ColorPickerSwatchTriggerProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.SwatchTrigger {...rest} className={slots.swatchTrigger({ className })} />
  );
}

export function ColorPickerSwatch({ className, ...rest }: ColorPickerSwatchProps) {
  const { slots } = useColorPicker();

  return <ColorPickerPrimitive.Swatch {...rest} className={slots.swatch({ className })} />;
}

export function ColorPickerSwatchIndicator({
  children,
  className,
  ...rest
}: ColorPickerSwatchIndicatorProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.SwatchIndicator
      {...rest}
      className={slots.swatchIndicator({ className })}
    >
      {children || <CheckIcon />}
    </ColorPickerPrimitive.SwatchIndicator>
  );
}

export function ColorPickerValueText({ className, ...rest }: ColorPickerValueTextProps) {
  const { slots } = useColorPicker();

  return <ColorPickerPrimitive.ValueText {...rest} className={slots.valueText({ className })} />;
}

export function ColorPickerValueSwatch({ className, ...rest }: ColorPickerValueSwatchProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.ValueSwatch {...rest} className={slots.valueSwatch({ className })} />
  );
}

export function ColorPickerArea({
  showDots = false,
  children,
  className,
  ...rest
}: ColorPickerAreaProps) {
  const { slots } = useColorPicker();

  return (
    <ColorPickerPrimitive.Area
      {...rest}
      className={slots.area({
        className: cn(
          {
            "after:pointer-events-none after:absolute after:inset-0 after:rounded-[inherit] after:bg-[radial-gradient(circle,#fff3_1px,#0000_1px)] after:bg-size-[8px_8px]":
              showDots,
          },
          className,
        ),
      })}
    >
      <ColorPickerPrimitive.AreaBackground className={slots.areaBackground()} />

      {children}
    </ColorPickerPrimitive.Area>
  );
}

export function ColorPickerAreaThumb({ className, ...rest }: ColorPickerAreaThumbProps) {
  const { slots } = useColorPicker();

  return <ColorPickerPrimitive.AreaThumb {...rest} className={slots.areaThumb({ className })} />;
}

export function ColorPickerInput({ channel = "hex", ...rest }: ColorPickerInputProps) {
  return <ColorPickerPrimitive.ChannelInput {...rest} channel={channel} />;
}

export function ColorPickerSwatchPreview({ className, ...rest }: ColorPickerSwatchPreviewProps) {
  const { slots } = useColorPicker();

  return (
    <ark.div
      {...rest}
      className={slots.inputSwatch({ className })}
      data-part="input-swatch"
      data-scope="color-picker"
    >
      <ColorPickerPrimitive.TransparencyGrid className={slots.inputSwatchGrid()} />
      <ColorPickerPrimitive.ValueSwatch className={slots.inputSwatchSwatch()} />
    </ark.div>
  );
}

/**
 * Compact preset that renders a swatch trigger, hex input, and standard
 * color picker popover in one component.
 */
export function ColorPickerField({ clearable = false, ...rest }: ColorPickerProps) {
  return (
    <ColorPickerRoot {...rest} clearable={clearable}>
      <ColorPickerControl clearable={false}>
        <InputGroup>
          <ColorPickerTrigger asChild>
            <InputGroup.Addon>
              <ColorPickerSwatchPreview />
            </InputGroup.Addon>
          </ColorPickerTrigger>
          <ColorPickerInput asChild>
            <InputGroup.Input clearable={false} />
          </ColorPickerInput>
          {clearable ? <ColorPickerClearTrigger /> : null}
        </InputGroup>
      </ColorPickerControl>

      <ColorPickerContent>
        <ColorPickerArea>
          <ColorPickerAreaThumb />
        </ColorPickerArea>
        <ColorPickerFieldView />
      </ColorPickerContent>
    </ColorPickerRoot>
  );
}

function ColorPickerFieldView() {
  const { slots } = useColorPicker();

  return (
    <ColorPickerView format="hsla">
      <div className={slots.channelRow()}>
        <ColorPickerEyeDropperTrigger />
        <div className={slots.channelStack()}>
          <ColorPickerChannelSlider channel="hue" />
          <ColorPickerChannelSlider channel="alpha">
            <ColorPickerTransparencyGrid />
          </ColorPickerChannelSlider>
        </div>
      </div>
    </ColorPickerView>
  );
}
// #endregion

// #region Display Names
ColorPickerRoot.displayName = "ColorPicker";
ColorPickerClearTrigger.displayName = "ColorPicker.ClearTrigger";
ColorPickerControl.displayName = "ColorPicker.Control";
ColorPickerTrigger.displayName = "ColorPicker.Trigger";
ColorPickerTransparencyGrid.displayName = "ColorPicker.TransparencyGrid";
ColorPickerContent.displayName = "ColorPicker.Content";
ColorPickerView.displayName = "ColorPicker.View";
ColorPickerChannelSlider.displayName = "ColorPicker.ChannelSlider";
ColorPickerEyeDropperTrigger.displayName = "ColorPicker.EyeDropperTrigger";
ColorPickerSwatchGroup.displayName = "ColorPicker.SwatchGroup";
ColorPickerSwatchTrigger.displayName = "ColorPicker.SwatchTrigger";
ColorPickerSwatch.displayName = "ColorPicker.Swatch";
ColorPickerSwatchIndicator.displayName = "ColorPicker.SwatchIndicator";
ColorPickerValueText.displayName = "ColorPicker.ValueText";
ColorPickerValueSwatch.displayName = "ColorPicker.ValueSwatch";
ColorPickerArea.displayName = "ColorPicker.Area";
ColorPickerAreaThumb.displayName = "ColorPicker.AreaThumb";
ColorPickerInput.displayName = "ColorPicker.Input";
ColorPickerSwatchPreview.displayName = "ColorPicker.SwatchPreview";
ColorPickerField.displayName = "ColorPicker.Field";
// #endregion

import type { ColorPickerRecipe } from "@pisagor/recipes/color-picker";
import { createContext } from "../../utils";

interface ColorPickerContextValue {
  slots: ColorPickerRecipe;
}

export const { ColorPickerContext: ColorPickerSlotsContext, useColorPicker } =
  createContext<ColorPickerContextValue>()({
    name: "ColorPicker",
  });

import { type CollectionItem, createListCollection } from "@ark-ui/react/collection";
import type {
  ComboboxClearTriggerProps,
  ComboboxControlProps,
  ComboboxEmptyProps,
  ComboboxItemGroupLabelProps,
  ComboboxListProps,
  ComboboxPositionerProps,
  ComboboxContentProps as ComboboxPrimitiveContentProps,
  ComboboxInputProps as ComboboxPrimitiveInputProps,
  ComboboxItemGroupProps as ComboboxPrimitiveItemGroupProps,
  ComboboxItemProps as ComboboxPrimitiveItemProps,
  ComboboxRootProps as ComboboxPrimitiveRootProps,
  ComboboxTriggerProps,
} from "@ark-ui/react/combobox";
import { Combobox as ComboboxPrimitive, useComboboxContext } from "@ark-ui/react/combobox";
import { Portal } from "@ark-ui/react/portal";
import { CaretUpDownIcon, CheckIcon, XIcon } from "@phosphor-icons/react";
import { type ComboboxVariantProps, comboboxRecipe } from "@pisagor/recipes/combobox";
import type { InputRootVariantProps } from "@pisagor/recipes/input";
import { cn } from "@pisagor/utils";
import type { ReactNode } from "react";
import { Button } from "../button";
import { InputGroup } from "../input-group";
import { ComboboxRootContext, useComboboxRoot } from "./combobox.context";

// #region Types
type FormControlVariant = "primary" | "secondary";

interface ComboboxPresetItem {
  label: string;
  value: string;
}

export type ComboboxRootProps<T extends CollectionItem = CollectionItem> = Omit<
  ComboboxPrimitiveRootProps<T>,
  "onValueChange"
> & {
  /** Visual shell variant. Defaults to `primary`. */
  variant?: FormControlVariant;
  onValueChange?: (value: string[]) => void;
  /**
   * Style recipe. Defaults to `comboboxRecipe` from `@pisagor/recipes/combobox`.
   *
   * @defaultValue comboboxRecipe
   */
  recipe?: typeof comboboxRecipe;
};

export interface ComboboxProps extends Omit<ComboboxRootProps, "children" | "collection"> {
  /**
   * Whether to show a clear button when the input has a value.
   *
   * @defaultValue false
   */
  clearable?: boolean;
  items?: Array<ComboboxPresetItem | string>;
}

export interface ComboboxInputProps
  extends Omit<ComboboxPrimitiveInputProps, "size">,
    InputRootVariantProps {
  /**
   * Whether to show a clear button when the input has a value.
   *
   * @defaultValue false
   */
  clearable?: boolean;
  /**
   * Whether the control is disabled.
   *
   * @defaultValue false
   */
  disabled?: boolean;
  /**
   * Whether to show the trigger button.
   *
   * @defaultValue true
   */
  showTrigger?: boolean;
}

export interface ComboboxItemGroupProps extends ComboboxPrimitiveItemGroupProps {
  /** The heading of the group */
  heading?: string | ReactNode;
}

export interface ComboboxItemProps extends ComboboxPrimitiveItemProps, ComboboxVariantProps {}

export type ComboboxFieldInputProps = ComboboxPrimitiveInputProps;

export interface ComboboxContentProps extends ComboboxPrimitiveContentProps {
  /**
   * Whether to render the content in a portal with a positioner.
   *
   * @defaultValue true
   */
  portalled?: boolean;
}

// #endregion

// #region Parts
export function ComboboxRoot<T extends CollectionItem = CollectionItem>({
  openOnClick = true,
  children,
  onValueChange,
  variant,
  recipe = comboboxRecipe,
  ...rest
}: ComboboxRootProps<T>) {
  const slots = recipe();

  return (
    <ComboboxRootContext value={{ slots }}>
      <ComboboxPrimitive.Root
        {...rest}
        onValueChange={onValueChange ? (details) => onValueChange(details.value) : undefined}
        openOnClick={openOnClick}
      >
        {children}
      </ComboboxPrimitive.Root>
    </ComboboxRootContext>
  );
}

export const ComboboxContext = ComboboxPrimitive.Context;

export function ComboboxControl({ className, ...rest }: ComboboxControlProps) {
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  return <ComboboxPrimitive.Control {...rest} className={slots.control({ className })} />;
}

export function ComboboxInput({
  size = "md",
  variant: variantProp,
  clearable = false,
  showTrigger = true,
  children,
  className,
  ...rest
}: ComboboxInputProps) {
  const { inputValue } = useComboboxContext();
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  return (
    <ComboboxControl data-size={size}>
      <InputGroup className={cn(className)} size={size} variant={variantProp}>
        {children}
        <ComboboxPrimitive.Input asChild>
          <InputGroup.Input {...rest} />
        </ComboboxPrimitive.Input>
        <InputGroup.Addon align="inline-end">
          {showTrigger && (
            <InputGroup.Button
              asChild
              className={slots.triggerHidden()}
              size="icon-xs"
              variant="ghost"
            >
              <ComboboxTrigger />
            </InputGroup.Button>
          )}
          {clearable && inputValue && (
            <ComboboxClearTrigger asChild>
              <InputGroup.Button aria-label="Clear" size="icon-xs" variant="ghost">
                <XIcon aria-hidden />
              </InputGroup.Button>
            </ComboboxClearTrigger>
          )}
        </InputGroup.Addon>
      </InputGroup>
    </ComboboxControl>
  );
}

export function ComboboxTrigger({ children, className, ...rest }: ComboboxTriggerProps) {
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  return (
    <ComboboxPrimitive.Trigger {...rest} asChild className={slots.trigger({ className })}>
      {children ?? (
        <Button aria-label="Toggle" className={slots.triggerButton()} variant="ghost">
          <CaretUpDownIcon aria-hidden />
        </Button>
      )}
    </ComboboxPrimitive.Trigger>
  );
}

export function ComboboxClearTrigger({
  "aria-label": ariaLabel = "Clear selected value(s)",
  ...rest
}: ComboboxClearTriggerProps) {
  return <ComboboxPrimitive.ClearTrigger {...rest} aria-label={ariaLabel} />;
}

/** Composable combobox input for custom controls (e.g. Tags Input). */
export function ComboboxFieldInput(props: ComboboxFieldInputProps) {
  return <ComboboxPrimitive.Input {...props} />;
}

export function ComboboxPositioner(props: ComboboxPositionerProps) {
  return <ComboboxPrimitive.Positioner {...props} />;
}

export function ComboboxContent({
  portalled = true,
  children,
  className,
  ...rest
}: ComboboxContentProps) {
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  const content = (
    <ComboboxPrimitive.Content {...rest} className={slots.content({ className })}>
      {children}
    </ComboboxPrimitive.Content>
  );

  if (!portalled) {
    return content;
  }

  return (
    <Portal>
      <ComboboxPositioner>{content}</ComboboxPositioner>
    </Portal>
  );
}

export function ComboboxItemGroup({ children, heading, ...rest }: ComboboxItemGroupProps) {
  return (
    <ComboboxPrimitive.ItemGroup {...rest}>
      {!!heading && <ComboboxItemGroupLabel>{heading}</ComboboxItemGroupLabel>}

      {children}
    </ComboboxPrimitive.ItemGroup>
  );
}

export function ComboboxItemGroupLabel({ className, ...rest }: ComboboxItemGroupLabelProps) {
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  return (
    <ComboboxPrimitive.ItemGroupLabel {...rest} className={slots.itemGroupLabel({ className })} />
  );
}

export function ComboboxItem({
  showIndicator = true,
  children,
  className,
  ...rest
}: ComboboxItemProps) {
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  return (
    <ComboboxPrimitive.Item
      {...rest}
      className={slots.item({ className, showIndicator })}
      persistFocus
    >
      {children}

      {showIndicator ? (
        <span className={slots.itemIndicator()}>
          <ComboboxPrimitive.ItemIndicator>
            <CheckIcon />
          </ComboboxPrimitive.ItemIndicator>
        </span>
      ) : null}
    </ComboboxPrimitive.Item>
  );
}

export function ComboboxEmpty({ children, className, ...rest }: ComboboxEmptyProps) {
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  return (
    <ComboboxPrimitive.Empty {...rest} className={slots.empty({ className })}>
      {children || "No results found. Try a different search."}
    </ComboboxPrimitive.Empty>
  );
}

export function ComboboxList({ className, ...rest }: ComboboxListProps) {
  const { slots = comboboxRecipe() } = useComboboxRoot() ?? {};

  return <ComboboxPrimitive.List {...rest} className={slots.list({ className })} />;
}
// #endregion

// #region Shorthand
export function ComboboxShorthand({ clearable = false, items = [], id, ...rest }: ComboboxProps) {
  const normalized = items.map((item) =>
    typeof item === "string" ? { label: item, value: item } : item,
  );
  const collection = createListCollection({ items: normalized });

  return (
    <ComboboxRoot {...rest} collection={collection}>
      <ComboboxInput clearable={clearable} id={id} />
      <ComboboxContent>
        <ComboboxList>
          {normalized.map((item) => (
            <ComboboxItem item={item} key={item.value}>
              {item.label}
            </ComboboxItem>
          ))}
        </ComboboxList>
      </ComboboxContent>
    </ComboboxRoot>
  );
}
// #endregion

// #region Display Names
ComboboxRoot.displayName = "Combobox.Root";
ComboboxControl.displayName = "Combobox.Control";
ComboboxInput.displayName = "Combobox.Input";
ComboboxTrigger.displayName = "Combobox.Trigger";
ComboboxClearTrigger.displayName = "Combobox.ClearTrigger";
ComboboxFieldInput.displayName = "Combobox.FieldInput";
ComboboxPositioner.displayName = "Combobox.Positioner";
ComboboxContent.displayName = "Combobox.Content";
ComboboxItemGroup.displayName = "Combobox.ItemGroup";
ComboboxItemGroupLabel.displayName = "Combobox.ItemGroupLabel";
ComboboxItem.displayName = "Combobox.Item";
ComboboxEmpty.displayName = "Combobox.Empty";
ComboboxList.displayName = "Combobox.List";
ComboboxShorthand.displayName = "Combobox";
// #endregion

import type { ComboboxRecipe } from "@pisagor/recipes/combobox";
import { createContext } from "../../utils";

export interface ComboboxRootContextValue {
  /** Slot class recipes from `comboboxRecipe`. */
  slots: ComboboxRecipe;
}

export const { ComboboxRootContext, useComboboxRoot } = createContext<ComboboxRootContextValue>()({
  name: "ComboboxRoot",
  strict: false,
});

