      { group: "Suggestions", label: "Slack", shortcut: "⌘S", value: "slack" },
      { group: "Suggestions", label: "YouTube", shortcut: "⌘Y", value: "youtube" },
      { group: "Suggestions", label: "Raycast", shortcut: "⌘R", value: "raycast" },
