                      <Command.Item item={item} key={item.value}>
                        {item.label}
                        <Command.Shortcut>{item.shortcut}</Command.Shortcut>
                      </Command.Item>
                    ))}
                  </Command.ItemGroup>
                ))}
              </Command.List>
            </Command.Content>
            <Command.Footer>
              <div className="flex items-center gap-2">
                <Kbd variant="outline">
                  <ArrowBendDownLeftIcon className="size-3" />
                </Kbd>
                <span className="text-muted-foreground">To select</span>
              </div>
            </Command.Footer>
          </Command>
        </Command.DialogContent>
      </Command.Dialog>
    );
  },
});

export const Groups = meta.story({
  render: () => {
    const initialItems = [
      { group: "Fruit", label: "Apple", value: "apple" },
      { group: "Fruit", label: "Banana", value: "banana" },
      { group: "Fruit", label: "Cherry", value: "cherry" },
      { group: "Countries", label: "United States", value: "us" },
      { group: "Countries", label: "United Kingdom", value: "uk" },
      { group: "Countries", label: "Germany", value: "de" },
    ];
    const { contains } = useFilter({ sensitivity: "base" });

    const { collection, filter } = useListCollection({
      filter: contains,
      groupBy: (item) => item.group,
      initialItems,
    });

    return (
      <Command collection={collection} onInputValueChange={({ inputValue }) => filter(inputValue)}>
        <Command.Input placeholder="Search..." />
        <Command.Content>
          <Command.Empty />
          <Command.List>
            {collection.group().map(([group, items], index) => (
              <>
                {index !== 0 && <Command.Separator />}
                <Command.ItemGroup heading={group} key={group}>
                  {items.map((item) => (
                    <Command.Item item={item} key={item.value}>
                      {item.label}
                    </Command.Item>
                  ))}
                </Command.ItemGroup>
              </>
            ))}
          </Command.List>
        </Command.Content>
      </Command>
    );
  },
});

export const WithFooter = meta.story({
  render: () => {
    const initialItems = [
      { group: "App", label: "Settings", shortcut: "⌘,", value: "settings" },
      {
        group: "App",
        label: "Keyboard Shortcuts",
        shortcut: "⌘K",
        value: "shortcuts",
      },
      { group: "App", label: "Help", shortcut: "⌘?", value: "help" },
    ];
    const { contains } = useFilter({ sensitivity: "base" });

    const { collection, filter } = useListCollection({
      filter: contains,
      groupBy: (item) => item.group,
      initialItems,
    });

    return (
      <Command collection={collection} onInputValueChange={({ inputValue }) => filter(inputValue)}>
        <Command.Input placeholder="Search..." />
        <Command.Content>
          <Command.Empty />
          <Command.List>
            {collection.group().map(([group, items]) => (
              <Command.ItemGroup heading={group} key={group}>
                {items.map((item) => (
                  <Command.Item item={item} key={item.value}>
                    {item.label}
                    <Command.Shortcut>{item.shortcut}</Command.Shortcut>
                  </Command.Item>
                ))}
              </Command.ItemGroup>
            ))}
          </Command.List>
        </Command.Content>
        <Command.Footer>
          <div className="flex items-center gap-2">
            <Kbd variant="outline">
              <ArrowBendDownLeftIcon className="size-3" />
            </Kbd>
            <span>Select</span>
          </div>
          <div className="flex items-center gap-2">
            <Kbd variant="outline">
              <ArrowUpIcon className="size-3" />
            </Kbd>
            <Kbd variant="outline">
              <ArrowDownIcon className="size-3" />
            </Kbd>
            <span>Navigate</span>
          </div>
        </Command.Footer>
      </Command>
    );
  },
});

