const ROLES: User["role"][] = ["Admin", "Editor", "Viewer"];
const STATUSES: User["status"][] = ["active", "inactive", "invited"];
const DEPARTMENTS = ["Engineering", "Design", "Marketing", "Sales", "Support"] as const;
const FIRST_NAMES = [
