export const Paginated = meta.story({
  render: () => {
    const [pagination, setPagination] = useState<PaginationState>({
      pageIndex: 0,
      pageSize: 8,
    });
    const columns = useUserColumns({ sortable: true });

    return (
      <DataGridShell>
        <DataGrid<User>
