          <DataGrid.Toolbar>
            <div className="flex flex-wrap items-center justify-between gap-3">
              <p className="font-medium text-sm">Paginated directory</p>
              <PageSizeSelect
                onChange={(pageSize) =>
                  setPagination((current) => ({ ...current, pageIndex: 0, pageSize }))
                }
