import type {
  DatePickerPresetTriggerProps,
  DatePickerContentProps as DatePickerPrimitiveContentProps,
  DatePickerInputProps as DatePickerPrimitiveInputProps,
  DatePickerRootProps as DatePickerPrimitiveRootProps,
  DatePickerTriggerProps as DatePickerPrimitiveTriggerProps,
  DatePickerValueTextProps,
} from "@ark-ui/react/date-picker";
import { DatePicker as DatePickerPrimitive, useDatePickerContext } from "@ark-ui/react/date-picker";
import { Portal } from "@ark-ui/react/portal";
import { CalendarIcon, ClockIcon, XIcon } from "@phosphor-icons/react";
import { calendarRecipe } from "@pisagor/recipes/calendar";
import { datePickerRecipe } from "@pisagor/recipes/date-picker";

import { useClearableInput } from "../../hooks";
import { Button } from "../button";
import { Calendar } from "../calendar";
import { CalendarSlotsContext } from "../calendar/calendar.context";
import { Input, type InputProps } from "../input";
import { InputGroup } from "../input-group";
import { DatePickerSlotsContext, useDatePicker } from "./date-picker.context";

// #region Types
type FormControlVariant = "primary" | "secondary";

export interface DatePickerTriggerProps extends DatePickerPrimitiveTriggerProps {
  /**
   * Whether to show a clear button when a date is selected.
   *
   * @defaultValue false
   */
  clearable?: boolean;
}

export interface DatePickerInputProps
  extends Omit<DatePickerPrimitiveInputProps, "size">,
    InputProps {
  /**
   * Whether to show a clear button when the input has a value.
   *
   * @defaultValue false
   */
  clearable?: boolean;
}

export interface DatePickerTimerProps extends InputProps {
  /**
   * Whether to show a clear button when the input has a value.
   *
   * @defaultValue false
   */
  clearable?: boolean;
}

export interface DatePickerContentProps extends DatePickerPrimitiveContentProps {
  /**
   * When `true` (default), auto-renders the standard month/year navigation and
   * day grid inside the content — no need to add calendar sub-components manually.
   */
  showCalendar?: boolean;
}

export interface DatePickerRootProps extends Omit<DatePickerPrimitiveRootProps, "onValueChange"> {
  /** Visual shell variant. Defaults to `primary`. */
  variant?: FormControlVariant;
  onValueChange?: (value: DatePickerRootProps["value"]) => void;
  /**
   * Style recipe. Defaults to `datePickerRecipe` from `@pisagor/recipes/date-picker`.
   *
   * @defaultValue datePickerRecipe
   */
  recipe?: typeof datePickerRecipe;
  /**
   * Calendar style recipe. Defaults to `calendarRecipe` from `@pisagor/recipes/calendar`.
   *
   * @defaultValue calendarRecipe
   */
  calendarRecipe?: typeof calendarRecipe;
}

// #endregion

// #region Parts
export function DatePickerRoot({
  variant,
  positioning = { placement: "top" },
  children,
  onValueChange,
  recipe = datePickerRecipe,
  calendarRecipe: calendarRecipeProp = calendarRecipe,
  ...rest
}: DatePickerRootProps) {
  const slots = recipe();
  const calendarSlots = calendarRecipeProp();

  return (
    <DatePickerSlotsContext value={{ slots }}>
      <CalendarSlotsContext value={{ slots: calendarSlots }}>
        <DatePickerPrimitive.Root
          {...rest}
          inline={false}
          onValueChange={onValueChange ? (details) => onValueChange(details.value) : undefined}
          positioning={positioning}
        >
          {children}
        </DatePickerPrimitive.Root>
      </CalendarSlotsContext>
    </DatePickerSlotsContext>
  );
}

export function DatePickerTrigger({
  clearable = false,
  children,
  className,
  ...rest
}: DatePickerTriggerProps) {
  const { slots } = useDatePicker();

  return (
    <DatePickerPrimitive.Control className={slots.control()}>
      <DatePickerPrimitive.Trigger {...rest} className={slots.trigger({ className })}>
        {children}
      </DatePickerPrimitive.Trigger>
      {clearable ? <DatePickerClearTrigger /> : null}
    </DatePickerPrimitive.Control>
  );
}

export function DatePickerInput({
  size,
  clearable = false,
  className,
  ...rest
}: DatePickerInputProps) {
  const { slots } = useDatePicker();

  return (
    <DatePickerPrimitive.Control>
      <InputGroup className={className} size={size}>
        <DatePickerPrimitive.Input {...rest} asChild>
          <InputGroup.Input clearable={false} />
        </DatePickerPrimitive.Input>

        <InputGroup.Addon align="inline-end">
          {clearable ? <DatePickerClearTrigger /> : null}
          <InputGroup.Button
            asChild
            data-part="button"
            data-scope="input-group"
            size="icon-xs"
            variant="ghost"
          >
            <DatePickerPrimitive.Trigger asChild>
              <Button aria-label="Open calendar" size="icon-md" variant="ghost">
                <CalendarIcon aria-hidden className={slots.icon()} />
              </Button>
            </DatePickerPrimitive.Trigger>
          </InputGroup.Button>
        </InputGroup.Addon>
      </InputGroup>
    </DatePickerPrimitive.Control>
  );
}

export function DatePickerClearTrigger() {
  const api = useDatePickerContext();

  if (api.disabled || api.readOnly || api.value.length === 0) {
    return null;
  }

  return (
    <DatePickerPrimitive.ClearTrigger asChild>
      <InputGroup.Button aria-label="Clear" size="icon-xs" type="button" variant="ghost">
        <XIcon />
      </InputGroup.Button>
    </DatePickerPrimitive.ClearTrigger>
  );
}

export function DatePickerTimer({
  clearable = false,
  defaultValue,
  disabled,
  readOnly,
  value,
  id,
  ref,
  onChange,
  className,
  classNames,
  ...rest
}: DatePickerTimerProps) {
  const { slots } = useDatePicker();
  const { canClear, handleChange, handleClear, mergedRef } = useClearableInput({
    clearable,
    defaultValue,
    disabled,
    onChange,
    readOnly,
    ref,
    value,
  });

  return (
    <InputGroup {...rest}>
      <InputGroup.Addon>
        <ClockIcon />
      </InputGroup.Addon>
      <InputGroup.Input
        className={slots.timer({ className })}
        classNames={classNames}
        clearable={false}
        defaultValue={defaultValue}
        disabled={disabled}
        id={id}
        onChange={handleChange}
        readOnly={readOnly}
        ref={mergedRef}
        step="1"
        type="time"
        value={value}
      />
      {canClear ? (
        <InputGroup.Addon align="inline-end">
          <Input.ClearButton onClear={handleClear} />
        </InputGroup.Addon>
      ) : null}
    </InputGroup>
  );
}

export function DatePickerContent({
  showCalendar = true,
  children,
  className,
  ...rest
}: DatePickerContentProps) {
  const { slots } = useDatePicker();

  return (
    <Portal>
      <DatePickerPrimitive.Positioner>
        <DatePickerPrimitive.Content {...rest} className={slots.content({ className })}>
          {showCalendar && !children ? (
            <>
              <Calendar.ViewControl>
                <Calendar.PrevTrigger />
                <Calendar.MonthSelect />
                <Calendar.YearSelect />
                <Calendar.NextTrigger />
              </Calendar.ViewControl>
              <Calendar.Table>
                <Calendar.WeekDays />
                <Calendar.TableDays />
              </Calendar.Table>
            </>
          ) : (
            children
          )}
        </DatePickerPrimitive.Content>
      </DatePickerPrimitive.Positioner>
    </Portal>
  );
}

export function DatePickerValueText({ className, ...rest }: DatePickerValueTextProps) {
  const { slots } = useDatePicker();

  return <DatePickerPrimitive.ValueText {...rest} className={slots.valueText({ className })} />;
}

export function DatePickerPresetTrigger(props: DatePickerPresetTriggerProps) {
  return <Calendar.PresetTrigger {...props} />;
}
// #endregion

// #region Display Names
DatePickerRoot.displayName = "DatePicker";
DatePickerTrigger.displayName = "DatePicker.Trigger";
DatePickerInput.displayName = "DatePicker.Input";
DatePickerClearTrigger.displayName = "DatePicker.ClearTrigger";
DatePickerTimer.displayName = "DatePicker.Timer";
DatePickerContent.displayName = "DatePicker.Content";
DatePickerValueText.displayName = "DatePicker.ValueText";
DatePickerPresetTrigger.displayName = "DatePicker.PresetTrigger";
// #endregion

import type { DatePickerRecipe } from "@pisagor/recipes/date-picker";
import { createContext } from "../../utils";

interface DatePickerContextValue {
  slots: DatePickerRecipe;
}

export const { DatePickerContext: DatePickerSlotsContext, useDatePicker } =
  createContext<DatePickerContextValue>()({
    name: "DatePicker",
  });

import {
  DatePickerClearTrigger,
  DatePickerContent,
  DatePickerInput,
  DatePickerPresetTrigger,
  DatePickerRoot,
  DatePickerTimer,
  DatePickerTrigger,
  DatePickerValueText,
} from "./date-picker";

export type {
  DatePickerPresetTriggerProps,
  DatePickerValueTextProps,
} from "@ark-ui/react/date-picker";

export type {
  DatePickerContentProps,
  DatePickerInputProps,
  DatePickerRootProps as DatePickerProps,
  DatePickerTimerProps,
  DatePickerTriggerProps,
} from "./date-picker";

export const DatePicker = Object.assign(DatePickerRoot, {
  ClearTrigger: DatePickerClearTrigger,
  Content: DatePickerContent,
  Input: DatePickerInput,
  PresetTrigger: DatePickerPresetTrigger,
  Timer: DatePickerTimer,
  Trigger: DatePickerTrigger,
  ValueText: DatePickerValueText,
});

import type {
  DialogBackdropProps,
  DialogCloseTriggerProps,
  DialogDescriptionProps,
  DialogContentProps as DialogPrimitiveContentProps,
  DialogPositionerProps as DialogPrimitivePositionerProps,
  DialogRootProps as DialogPrimitiveRootProps,
  DialogTitleProps,
  DialogTriggerProps,
} from "@ark-ui/react/dialog";
import { Dialog as DialogPrimitive } from "@ark-ui/react/dialog";
import { ark } from "@ark-ui/react/factory";
import { Portal } from "@ark-ui/react/portal";
import { XIcon } from "@phosphor-icons/react";
import { type DialogVariantProps, dialogRecipe } from "@pisagor/recipes/dialog";
import type { ComponentProps, ReactNode } from "react";
import { Button } from "../button";
import { ScrollArea } from "../scroll-area";
import { DialogContext, useDialog } from "./dialog.context";

// #region Types
export interface DialogRootProps extends DialogPrimitiveRootProps {
  /**
   * Style recipe. Defaults to `dialogRecipe` from `@pisagor/recipes/dialog`.
   *
   * @defaultValue dialogRecipe
   */
  recipe?: typeof dialogRecipe;
}

export interface DialogContentProps extends DialogPrimitiveContentProps, DialogVariantProps {
  /**
   * Whether to stick the dialog to the bottom of the screen on mobile.
   *
   * @defaultValue true
   */
  bottomStickOnMobile?: boolean;
  /**
   * Whether to show a close button at the top right corner.
   *
   * @defaultValue true
   */
  showCloseButton?: boolean;
}

export interface DialogBodyProps extends ComponentProps<typeof ark.div> {
  /**
   * Whether to add a fade effect to the scroll area.
   *
   * @defaultValue false
   */
  scrollFade?: boolean;
}

export type DialogHeaderProps = ComponentProps<typeof ark.div>;

export interface DialogPositionerProps extends DialogPrimitivePositionerProps {
  bottomStickOnMobile?: boolean;
}

export type DialogFooterProps = ComponentProps<typeof ark.div>;

export interface DialogProps extends Omit<DialogRootProps, "title"> {
  /** Footer actions. */
  actions?: ReactNode;
  /** Header description content. */
  description?: ReactNode;
  /** Header title content. */
  title?: ReactNode;
  /** Control that opens the dialog. */
  trigger?: ReactNode;
}
// #endregion

// #region Parts
export function DialogRoot({ modal = true, recipe = dialogRecipe, ...rest }: DialogRootProps) {
  const slots = recipe();

  return (
    <DialogContext value={{ modal, slots }}>
      <DialogPrimitive.Root {...rest} modal={modal} />
    </DialogContext>
  );
}

export function DialogTrigger(props: DialogTriggerProps) {
  return <DialogPrimitive.Trigger {...props} />;
}

export function DialogBackdrop({ className, ...rest }: DialogBackdropProps) {
  const { modal, slots } = useDialog();

  if (!modal) {
    return null;
  }

  return <DialogPrimitive.Backdrop {...rest} className={slots.backdrop({ className })} />;
}

export function DialogPositioner({
  bottomStickOnMobile,
  className,
  ...rest
}: DialogPositionerProps) {
  const { slots } = useDialog();

  return (
    <DialogPrimitive.Positioner
      {...rest}
      className={slots.positioner({ bottomStickOnMobile, className })}
    />
  );
}

export function DialogContent({
  size = "md",
  bottomStickOnMobile = true,
  showCloseButton = true,
  children,
  className,
  ...rest
}: DialogContentProps) {
  const { slots } = useDialog();

  return (
    <DialogPrimitive.Content
      {...rest}
      className={slots.content({ bottomStickOnMobile, className, size })}
    >
      {children}

      {!!showCloseButton && (
        <DialogCloseTrigger asChild>
          <Button aria-label="Close" className={slots.inline()} size="icon-sm" variant="ghost">
            <XIcon />
          </Button>
        </DialogCloseTrigger>
      )}
    </DialogPrimitive.Content>
  );
}

export function DialogBody({ scrollFade = false, className, ...rest }: DialogBodyProps) {
  const { slots } = useDialog();

  return (
    <ScrollArea scrollFade={scrollFade}>
      <ark.div
        {...rest}
        className={slots.body({ className })}
        data-part="body"
        data-scope="dialog"
      />
    </ScrollArea>
  );
}

export function DialogHeader({ children, className, ...rest }: DialogHeaderProps) {
  const { slots } = useDialog();

  return (
    <ark.div
      {...rest}
      className={slots.header({ className })}
      data-part="header"
      data-scope="dialog"
    >
      {children}
    </ark.div>
  );
}

export function DialogTitle({ className, ...rest }: DialogTitleProps) {
  const { slots } = useDialog();

  return <DialogPrimitive.Title {...rest} className={slots.title({ className })} />;
}

export function DialogDescription({ className, ...rest }: DialogDescriptionProps) {
  const { slots } = useDialog();

  return <DialogPrimitive.Description {...rest} className={slots.description({ className })} />;
}

export function DialogCloseTrigger(props: DialogCloseTriggerProps) {
  return <DialogPrimitive.CloseTrigger {...props} />;
}

export function DialogFooter({ className, ...rest }: DialogFooterProps) {
  const { slots } = useDialog();

  return (
    <ark.div
      {...rest}
      className={slots.footer({ className })}
      data-part="footer"
      data-scope="dialog"
    />
  );
}
// #endregion

// #region Shorthand
export function DialogShorthand({
  actions,
  children,
  description,
  title,
  trigger,
  ...rest
}: DialogProps) {
  return (
    <DialogRoot {...rest}>
      {trigger !== undefined && <DialogTrigger asChild>{trigger}</DialogTrigger>}

      <Portal>
        <DialogBackdrop />

        <DialogPositioner>
          <DialogContent>
            {(title !== undefined || description !== undefined) && (
              <DialogHeader>
                {title !== undefined && <DialogTitle>{title}</DialogTitle>}

                {description !== undefined && <DialogDescription>{description}</DialogDescription>}
              </DialogHeader>
            )}

            {children !== undefined && <DialogBody>{children}</DialogBody>}

            {actions !== undefined && <DialogFooter>{actions}</DialogFooter>}
          </DialogContent>
        </DialogPositioner>
      </Portal>
    </DialogRoot>
  );
}
// #endregion

// #region Display Names
DialogRoot.displayName = "Dialog.Root";
DialogTrigger.displayName = "Dialog.Trigger";
DialogBackdrop.displayName = "Dialog.Backdrop";
DialogPositioner.displayName = "Dialog.Positioner";
DialogContent.displayName = "Dialog.Content";
DialogBody.displayName = "Dialog.Body";
DialogHeader.displayName = "Dialog.Header";
DialogTitle.displayName = "Dialog.Title";
DialogDescription.displayName = "Dialog.Description";
DialogCloseTrigger.displayName = "Dialog.CloseTrigger";
DialogFooter.displayName = "Dialog.Footer";
DialogShorthand.displayName = "Dialog";
// #endregion

import type { DialogRecipe } from "@pisagor/recipes/dialog";
import { createContext } from "../../utils";

interface DialogContextValue {
  /**
   * Used internally to show or hide the overlay.
   *
   * @defaultValue true
   *
   * @remarks
   * When `false`, the overlay is not rendered and content outside the dialog stays interactable.
   */
  modal?: boolean;
  /** Slot class recipes from `dialogRecipe`. */
  slots: DialogRecipe;
}

export const { DialogContext, useDialog } = createContext<DialogContextValue>()({
  name: "Dialog",
});

