import type {
  DrawerBackdropProps,
  DrawerCloseTriggerProps,
  DrawerGrabberProps,
  DrawerContentProps as DrawerPrimitiveContentProps,
  DrawerPositionerProps as DrawerPrimitivePositionerProps,
  DrawerRootProps as DrawerPrimitiveRootProps,
  DrawerTitleProps,
  DrawerTriggerProps,
} from "@ark-ui/react/drawer";
import { Drawer as DrawerPrimitive } from "@ark-ui/react/drawer";
import { ark } from "@ark-ui/react/factory";
import { Portal } from "@ark-ui/react/portal";
import { type DrawerVariantProps, drawerRecipe } from "@pisagor/recipes/drawer";
import type { ComponentProps } from "react";
import { ScrollArea } from "../scroll-area";
import { DrawerContext, useDrawer } from "./drawer.context";

// #region Types
export interface DrawerRootProps extends DrawerPrimitiveRootProps {
  /**
   * Style recipe. Defaults to `drawerRecipe` from `@pisagor/recipes/drawer`.
   *
   * @defaultValue drawerRecipe
   */
  recipe?: typeof drawerRecipe;
}

export type DrawerPositionerProps = DrawerPrimitivePositionerProps &
  Pick<DrawerVariantProps, "variant">;

export type DrawerContentProps = DrawerPrimitiveContentProps & Pick<DrawerVariantProps, "variant">;

export interface DrawerHeaderProps extends ComponentProps<typeof ark.div> {
  /** The description of the drawer */
  description?: string;
  /** The title of the drawer */
  title?: string;
}

export interface DrawerBodyProps extends ComponentProps<typeof ark.div> {
  /**
   * Whether to add a fade effect to the scroll area.
   *
   * @defaultValue false
   */
  scrollFade?: boolean;
}

export type DrawerContentInnerProps = ComponentProps<typeof ark.div>;

export type DrawerDescriptionProps = ComponentProps<typeof ark.div>;

export type DrawerFooterProps = ComponentProps<typeof ark.div>;
// #endregion

// #region Parts
export function DrawerRoot({ recipe = drawerRecipe, ...rest }: DrawerRootProps) {
  const slots = recipe();

  return (
    <DrawerContext value={{ slots }}>
      <DrawerPrimitive.Root {...rest} />
    </DrawerContext>
  );
}

export function DrawerTrigger(props: DrawerTriggerProps) {
  return <DrawerPrimitive.Trigger {...props} />;
}

export function DrawerBackdrop({ className, ...rest }: DrawerBackdropProps) {
  const { slots } = useDrawer();

  return <DrawerPrimitive.Backdrop {...rest} className={slots.backdrop({ className })} />;
}

export function DrawerPositioner({
  variant = "default",
  className,
  ...rest
}: DrawerPositionerProps) {
  const { slots } = useDrawer();

  return (
    <DrawerPrimitive.Positioner {...rest} className={slots.positioner({ className, variant })} />
  );
}

const SWIPE_DIRECTION_TO_PLACEMENT = {
  down: "down",
  end: "right",
  start: "left",
  up: "up",
} as const;

export function DrawerContent({
  variant = "default",
  children,
  className,
  ...rest
}: DrawerContentProps) {
  const { slots } = useDrawer();

  return (
    <Portal>
      <DrawerBackdrop />
      <DrawerPrimitive.Context>
        {({ swipeDirection }) => (
          <DrawerPositioner variant={variant}>
            <DrawerPrimitive.Content
              {...rest}
              className={slots.content({
                className,
                placement: SWIPE_DIRECTION_TO_PLACEMENT[swipeDirection],
                variant,
              })}
            >
              <DrawerGrabber />

              {children}
            </DrawerPrimitive.Content>
          </DrawerPositioner>
        )}
      </DrawerPrimitive.Context>
    </Portal>
  );
}

export function DrawerContentInner({ className, ...rest }: DrawerContentInnerProps) {
  const { slots } = useDrawer();

  return (
    <ark.div
      {...rest}
      className={slots.contentInner({ className })}
      data-part="content-inner"
      data-scope="drawer"
    />
  );
}

export function DrawerGrabber({ className, ...rest }: DrawerGrabberProps) {
  const { slots } = useDrawer();

  return (
    <ark.div className={slots.grabberWrapper()}>
      <DrawerPrimitive.Grabber {...rest} className={slots.grabber({ className })}>
        <DrawerPrimitive.GrabberIndicator className={slots.grabberIcon()} />
      </DrawerPrimitive.Grabber>
    </ark.div>
  );
}

export function DrawerHeader({
  children,
  description,
  title,
  className,
  ...rest
}: DrawerHeaderProps) {
  const { slots } = useDrawer();

  return (
    <ark.div
      {...rest}
      className={slots.header({ className })}
      data-part="header"
      data-scope="drawer"
    >
      {!!title && <DrawerTitle>{title}</DrawerTitle>}

      {!!description && <DrawerDescription>{description}</DrawerDescription>}

      {children}
    </ark.div>
  );
}

export function DrawerTitle({ className, ...rest }: DrawerTitleProps) {
  const { slots } = useDrawer();

  return <DrawerPrimitive.Title {...rest} className={slots.title({ className })} />;
}

export function DrawerDescription({ className, ...rest }: DrawerDescriptionProps) {
  const { slots } = useDrawer();

  return (
    <ark.div
      {...rest}
      className={slots.description({ className })}
      data-part="description"
      data-scope="drawer"
    />
  );
}

export function DrawerBody({ scrollFade = false, className, ...rest }: DrawerBodyProps) {
  const { slots } = useDrawer();

  return (
    <ScrollArea scrollFade={scrollFade}>
      <ark.div
        {...rest}
        className={slots.body({ className })}
        data-part="body"
        data-scope="drawer"
      />
    </ScrollArea>
  );
}

export function DrawerCloseTrigger(props: DrawerCloseTriggerProps) {
  return <DrawerPrimitive.CloseTrigger {...props} />;
}

export function DrawerFooter({ className, ...rest }: DrawerFooterProps) {
  const { slots } = useDrawer();

  return (
    <ark.div
      {...rest}
      className={slots.footer({ className })}
      data-part="footer"
      data-scope="drawer"
    />
  );
}
// #endregion

// #region Display Names
DrawerRoot.displayName = "Drawer";
DrawerTrigger.displayName = "Drawer.Trigger";
DrawerBackdrop.displayName = "Drawer.Backdrop";
DrawerPositioner.displayName = "Drawer.Positioner";
DrawerContent.displayName = "Drawer.Content";
DrawerContentInner.displayName = "Drawer.ContentInner";
DrawerGrabber.displayName = "Drawer.Grabber";
DrawerHeader.displayName = "Drawer.Header";
DrawerTitle.displayName = "Drawer.Title";
DrawerDescription.displayName = "Drawer.Description";
DrawerBody.displayName = "Drawer.Body";
DrawerCloseTrigger.displayName = "Drawer.CloseTrigger";
DrawerFooter.displayName = "Drawer.Footer";
// #endregion

import type { DrawerRecipe } from "@pisagor/recipes/drawer";
import { createContext } from "../../utils";

interface DrawerContextValue {
  /** Slot class recipes from `drawerRecipe`. */
  slots: DrawerRecipe;
}

export const { DrawerContext, useDrawer } = createContext<DrawerContextValue>()({
  name: "Drawer",
});

import { Portal } from "@ark-ui/react";
import { ark } from "@ark-ui/react/factory";
import type {
  MenuArrowProps,
  MenuCheckboxItemProps,
  MenuContentProps,
  MenuItemGroupLabelProps,
  MenuItemGroupProps,
  MenuItemProps,
  MenuPositionerProps,
  MenuRadioItemGroupProps,
  MenuRadioItemProps,
  MenuRootProps,
  MenuSeparatorProps,
  MenuTriggerItemProps,
  MenuTriggerProps,
} from "@ark-ui/react/menu";
import { Menu as MenuPrimitive } from "@ark-ui/react/menu";
import { CaretRightIcon, CheckIcon } from "@phosphor-icons/react";
import {
  type DropdownMenuItemVariantProps,
  dropdownMenuItemRecipe,
  dropdownMenuRecipe,
} from "@pisagor/recipes/dropdown-menu";
import type { ComponentProps } from "react";
import { DropdownMenuContext, useDropdownMenu } from "./dropdown-menu.context";

// #region Types
export interface DropdownMenuItemGroupProps extends MenuItemGroupProps {
  /** The heading of the menu item group. */
  heading?: string;
}

export interface DropdownMenuItemProps extends MenuItemProps, DropdownMenuItemVariantProps {
  /**
   * Style recipe. Defaults to `dropdownMenuItemRecipe` from `@pisagor/recipes/dropdown-menu`.
   *
   * @defaultValue dropdownMenuItemRecipe
   */
  recipe?: typeof dropdownMenuItemRecipe;
}

export interface DropdownMenuRadioItemGroupProps extends MenuRadioItemGroupProps {
  /** The heading of the menu radio item group. */
  heading?: string;
}

export type DropdownMenuRootProps = MenuRootProps;

export type DropdownMenuTriggerProps = MenuTriggerProps;

export type DropdownMenuPositionerProps = MenuPositionerProps;

export interface DropdownMenuCheckboxItemProps extends MenuCheckboxItemProps {
  /**
   * Style recipe. Defaults to `dropdownMenuItemRecipe` from `@pisagor/recipes/dropdown-menu`.
   *
   * @defaultValue dropdownMenuItemRecipe
   */
  recipe?: typeof dropdownMenuItemRecipe;
}

export type DropdownMenuItemGroupLabelProps = MenuItemGroupLabelProps;

export interface DropdownMenuRadioItemProps extends MenuRadioItemProps {
  /**
   * Style recipe. Defaults to `dropdownMenuItemRecipe` from `@pisagor/recipes/dropdown-menu`.
   *
   * @defaultValue dropdownMenuItemRecipe
   */
  recipe?: typeof dropdownMenuItemRecipe;
}

export interface DropdownMenuSubContentProps extends MenuContentProps {
  /**
   * Style recipe. Defaults to `dropdownMenuRecipe` from `@pisagor/recipes/dropdown-menu`.
   *
   * @defaultValue dropdownMenuRecipe
   */
  recipe?: typeof dropdownMenuRecipe;
}

export type DropdownMenuArrowProps = MenuArrowProps;

export type DropdownMenuSeparatorProps = MenuSeparatorProps;

export interface DropdownMenuTriggerItemProps extends MenuTriggerItemProps {
  /**
   * Style recipe. Defaults to `dropdownMenuItemRecipe` from `@pisagor/recipes/dropdown-menu`.
   *
   * @defaultValue dropdownMenuItemRecipe
   */
  recipe?: typeof dropdownMenuItemRecipe;
}

export interface DropdownMenuContentProps extends MenuContentProps {
  /**
   * Style recipe. Defaults to `dropdownMenuRecipe` from `@pisagor/recipes/dropdown-menu`.
   *
   * @defaultValue dropdownMenuRecipe
   */
  recipe?: typeof dropdownMenuRecipe;
}

export type DropdownMenuShortcutProps = ComponentProps<typeof ark.span>;
// #endregion

// #region Parts
export function DropdownMenuRoot({
  positioning = { placement: "bottom-end" },
  ...rest
}: DropdownMenuRootProps) {
  return <MenuPrimitive.Root {...rest} positioning={positioning} />;
}

export function DropdownMenuTrigger(props: DropdownMenuTriggerProps) {
  return <MenuPrimitive.Trigger {...props} />;
}

export function DropdownMenuPositioner({ className, ...rest }: DropdownMenuPositionerProps) {
  const context = useDropdownMenu();
  const slots = context?.slots ?? dropdownMenuRecipe();

  return <MenuPrimitive.Positioner {...rest} className={slots.positioner({ className })} />;
}

export function DropdownMenuContent({
  children,
  recipe = dropdownMenuRecipe,
  className,
  ...rest
}: DropdownMenuContentProps) {
  const slots = recipe();

  return (
    <DropdownMenuContext value={{ slots }}>
      <Portal>
        <DropdownMenuPositioner>
          <MenuPrimitive.Content {...rest} className={slots.content({ className })}>
            {children}
          </MenuPrimitive.Content>
        </DropdownMenuPositioner>
      </Portal>
    </DropdownMenuContext>
  );
}

export function DropdownMenuItemGroup({ children, heading, ...rest }: DropdownMenuItemGroupProps) {
  return (
    <MenuPrimitive.ItemGroup {...rest}>
      {!!heading && <DropdownMenuItemGroupLabel>{heading}</DropdownMenuItemGroupLabel>}

      {children}
    </MenuPrimitive.ItemGroup>
  );
}

export function DropdownMenuSeparator({ className, ...rest }: DropdownMenuSeparatorProps) {
  const context = useDropdownMenu();
  const slots = context?.slots ?? dropdownMenuRecipe();

  return <MenuPrimitive.Separator {...rest} className={slots.separator({ className })} />;
}

export function DropdownMenuItem({
  variant = "default",
  recipe = dropdownMenuItemRecipe,
  className,
  ...rest
}: DropdownMenuItemProps) {
  return (
    <MenuPrimitive.Item
      {...rest}
      className={recipe({ variant }).base({ className })}
      data-variant={variant}
    />
  );
}

export function DropdownMenuQuickItem({
  variant = "default",
  recipe = dropdownMenuItemRecipe,
  className,
  ...rest
}: DropdownMenuItemProps) {
  const context = useDropdownMenu();
  const slots = context?.slots ?? dropdownMenuRecipe();

  return (
    <MenuPrimitive.Item
      {...rest}
      className={recipe({ variant }).base({
        className: slots.quickItem({ className }),
      })}
    />
  );
}

export function DropdownMenuCheckboxItem({
  children,
  recipe = dropdownMenuItemRecipe,
  className,
  ...rest
}: DropdownMenuCheckboxItemProps) {
  const slots = recipe({ inset: true, variant: "default" });

  return (
    <MenuPrimitive.CheckboxItem {...rest} className={slots.base({ className })}>
      <MenuPrimitive.ItemIndicator className={slots.indicator()}>
        <CheckIcon />
      </MenuPrimitive.ItemIndicator>

      <MenuPrimitive.ItemText className={slots.text()}>{children}</MenuPrimitive.ItemText>
    </MenuPrimitive.CheckboxItem>
  );
}

export function DropdownMenuRadioItemGroup({
  children,
  heading,
  ...rest
}: DropdownMenuRadioItemGroupProps) {
  return (
    <MenuPrimitive.RadioItemGroup {...rest}>
      {!!heading && <DropdownMenuItemGroupLabel>{heading}</DropdownMenuItemGroupLabel>}

      {children}
    </MenuPrimitive.RadioItemGroup>
  );
}

export function DropdownMenuItemGroupLabel({
  className,
  ...rest
}: DropdownMenuItemGroupLabelProps) {
  const context = useDropdownMenu();
  const slots = context?.slots ?? dropdownMenuRecipe();

  return <MenuPrimitive.ItemGroupLabel {...rest} className={slots.itemGroupLabel({ className })} />;
}

export function DropdownMenuRadioItem({
  children,
  recipe = dropdownMenuItemRecipe,
  className,
  ...rest
}: DropdownMenuRadioItemProps) {
  const slots = recipe({ inset: true, variant: "default" });

  return (
    <MenuPrimitive.RadioItem {...rest} className={slots.base({ className })}>
      <MenuPrimitive.ItemIndicator className={slots.indicator()}>
        <CheckIcon />
      </MenuPrimitive.ItemIndicator>

      <MenuPrimitive.ItemText className={slots.text()}>{children}</MenuPrimitive.ItemText>
    </MenuPrimitive.RadioItem>
  );
}

export function DropdownMenuSub(props: DropdownMenuRootProps) {
  return <DropdownMenuRoot {...props} />;
}

export function DropdownMenuSubContent({
  recipe = dropdownMenuRecipe,
  className,
  ...rest
}: DropdownMenuSubContentProps) {
  const slots = recipe();

  return (
    <DropdownMenuContext value={{ slots }}>
      <Portal>
        <DropdownMenuPositioner>
          <MenuPrimitive.Content {...rest} className={slots.content({ className })} />
        </DropdownMenuPositioner>
      </Portal>
    </DropdownMenuContext>
  );
}

export function DropdownMenuTriggerItem({
  children,
  recipe = dropdownMenuItemRecipe,
  className,
  ...rest
}: DropdownMenuTriggerItemProps) {
  return (
    <MenuPrimitive.TriggerItem
      {...rest}
      className={recipe({ variant: "default" }).base({ className })}
    >
      {children}

      <DropdownMenuShortcut>
        <CaretRightIcon />
      </DropdownMenuShortcut>
    </MenuPrimitive.TriggerItem>
  );
}

export function DropdownMenuShortcut({ className, ...rest }: DropdownMenuShortcutProps) {
  const context = useDropdownMenu();
  const slots = context?.slots ?? dropdownMenuRecipe();

  return (
    <ark.span
      {...rest}
      className={slots.shortcut({ className })}
      data-part="shortcut"
      data-scope="dropdown-menu"
    />
  );
}

export function DropdownMenuArrow({ style, ...rest }: DropdownMenuArrowProps) {
  const context = useDropdownMenu();
  const slots = context?.slots ?? dropdownMenuRecipe();

  return (
    <MenuPrimitive.Arrow
      {...rest}
      style={{
        "--arrow-background": "var(--popover)",
        "--arrow-size": "calc(1.5 * var(--spacing))",
        ...style,
        left: "20px",
      }}
    >
      <MenuPrimitive.ArrowTip className={slots.arrowTip()} />
    </MenuPrimitive.Arrow>
  );
}
// #endregion

// #region Display Names
DropdownMenuRoot.displayName = "DropdownMenu";
DropdownMenuTrigger.displayName = "DropdownMenu.Trigger";
DropdownMenuPositioner.displayName = "DropdownMenu.Positioner";
DropdownMenuContent.displayName = "DropdownMenu.Content";
DropdownMenuItemGroup.displayName = "DropdownMenu.ItemGroup";
DropdownMenuSeparator.displayName = "DropdownMenu.Separator";
DropdownMenuItem.displayName = "DropdownMenu.Item";
DropdownMenuQuickItem.displayName = "DropdownMenu.QuickItem";
DropdownMenuCheckboxItem.displayName = "DropdownMenu.CheckboxItem";
DropdownMenuRadioItemGroup.displayName = "DropdownMenu.RadioItemGroup";
DropdownMenuItemGroupLabel.displayName = "DropdownMenu.ItemGroupLabel";
DropdownMenuRadioItem.displayName = "DropdownMenu.RadioItem";
DropdownMenuSub.displayName = "DropdownMenu.Sub";
DropdownMenuSubContent.displayName = "DropdownMenu.SubContent";
DropdownMenuTriggerItem.displayName = "DropdownMenu.TriggerItem";
DropdownMenuShortcut.displayName = "DropdownMenu.Shortcut";
DropdownMenuArrow.displayName = "DropdownMenu.Arrow";
// #endregion

import type { DropdownMenuRecipe } from "@pisagor/recipes/dropdown-menu";
import { createContext } from "../../utils";

interface DropdownMenuContextValue {
  slots: DropdownMenuRecipe;
}

export const { DropdownMenuContext, useDropdownMenu } = createContext<DropdownMenuContextValue>()({
  name: "DropdownMenu",
  strict: false,
});

import type {
  EditableAreaProps,
  EditableCancelTriggerProps,
  EditableControlProps,
  EditableEditTriggerProps,
  EditableInputProps as EditablePrimitiveInputProps,
  EditablePreviewProps as EditablePrimitivePreviewProps,
  EditableRootProps as EditablePrimitiveRootProps,
  EditableSubmitTriggerProps,
} from "@ark-ui/react/editable";
import { Editable as EditablePrimitive } from "@ark-ui/react/editable";
import { buttonRecipe } from "@pisagor/recipes/button";
import { editableRecipe } from "@pisagor/recipes/editable";

import { cn } from "@pisagor/utils";
import type { ButtonProps } from "../button";
import { useFormControlSurface } from "../surface/use-form-control-surface";
import { EditableContext, useEditable } from "./editable.context";

// #region Types
type FormControlVariant = "primary" | "secondary";

export type EditableRootProps = Omit<
  EditablePrimitiveRootProps,
  "onValueChange" | "value" | "defaultValue"
>;

export interface EditableProps extends EditableRootProps {
  /** The orientation of the editable */
  orientation?: "horizontal" | "vertical";
  /**
   * Initial text value when uncontrolled.
   *
   * @remarks
   * Ignored when `value` is set.
   */
  defaultValue?: string;
  /**
   * Controlled text value.
   *
   * @remarks
   * When set, `defaultValue` is ignored. Pair with `onValueChange` to handle updates.
   */
  value?: string;
  /**
   * Called when the text value changes.
   *
   * @remarks
   * Receives the string value directly, not Ark UI event details.
   */
  onValueChange?: (value: string) => void;
  /**
   * Style recipe. Defaults to `editableRecipe` from `@pisagor/recipes/editable`.
   *
   * @defaultValue editableRecipe
   */
  recipe?: typeof editableRecipe;
}

export interface EditableInputProps extends Omit<EditablePrimitiveInputProps, "size"> {}

export interface EditablePreviewProps extends EditablePrimitivePreviewProps {
  /** Form shell variant. Defaults to `primary`. */
  controlVariant?: FormControlVariant;
  /**
   * The size of the preview
   *
   * @defaultValue "md"
   */
  size?: ButtonProps["size"];
  /**
   * The variant of the preview
   *
   * @defaultValue "outline"
   */
  variant?: ButtonProps["variant"];
  /**
   * Button style recipe. Defaults to `buttonRecipe` from `@pisagor/recipes/button`.
   *
   * @defaultValue buttonRecipe
   */
  buttonRecipe?: typeof buttonRecipe;
}

// #endregion

// #region Parts
export function EditableRoot({
  orientation = "horizontal",
  defaultValue,
  value,
  onValueChange,
  recipe = editableRecipe,
  className,
  ...rest
}: EditableProps) {
  const handleValueChange = onValueChange
    ? (details: Parameters<NonNullable<EditablePrimitiveRootProps["onValueChange"]>>[0]) =>
        onValueChange(details.value)
    : undefined;

  const slots = recipe();

  return (
    <EditableContext value={{ slots }}>
      <EditablePrimitive.Root
        {...rest}
        className={slots.base({ className })}
        data-orientation={orientation}
        defaultValue={defaultValue}
        onValueChange={handleValueChange}
        value={value}
      />
    </EditableContext>
  );
}

export function EditableArea({ className, ...rest }: EditableAreaProps) {
  const { slots } = useEditable();

  return <EditablePrimitive.Area {...rest} className={slots.area({ className })} />;
}

export function EditableInput(props: EditableInputProps) {
  return <EditablePrimitive.Input {...props} />;
}

export function EditablePreview({
  controlVariant,
  size = "md",
  variant = "outline",
  buttonRecipe: buttonRecipeProp = buttonRecipe,
  className,
  ...rest
}: EditablePreviewProps) {
  const { slots } = useEditable();
  const resolved = {
    surfaceVariant: useFormControlSurface(),
    variant: controlVariant ?? ("primary" as FormControlVariant),
  };
  const controlProps = { "data-variant": resolved.variant };
  const previewShellClass =
    resolved.variant === "secondary" && resolved.surfaceVariant === "default"
      ? "bg-muted/40 shadow-none hover:bg-muted/40 dark:hover:bg-muted/40"
      : resolved.variant === "secondary" && resolved.surfaceVariant
        ? "bg-background shadow-none hover:bg-background dark:hover:bg-background/90"
        : resolved.variant === "secondary"
          ? "bg-muted/40 shadow-none hover:bg-muted/40 dark:hover:bg-muted/40"
          : undefined;

  return (
    <EditablePrimitive.Preview
      {...rest}
      {...controlProps}
      className={cn(
        buttonRecipeProp({ clickEffect: false, size, variant }).base(),
        previewShellClass,
        slots.preview(),
        previewShellClass ? "dark:hover:bg-transparent" : undefined,
        className,
      )}
    />
  );
}

export function EditableControl({ className, ...rest }: EditableControlProps) {
  const { slots } = useEditable();

  return <EditablePrimitive.Control {...rest} className={slots.control({ className })} />;
}

export function EditableEditTrigger(props: EditableEditTriggerProps) {
  return <EditablePrimitive.EditTrigger {...props} />;
}

export function EditableCancelTrigger(props: EditableCancelTriggerProps) {
  return <EditablePrimitive.CancelTrigger {...props} />;
}

export function EditableSubmitTrigger(props: EditableSubmitTriggerProps) {
  return <EditablePrimitive.SubmitTrigger {...props} />;
}
// #endregion

// #region Display Names
EditableRoot.displayName = "Editable";
EditableArea.displayName = "Editable.Area";
EditableInput.displayName = "Editable.Input";
EditablePreview.displayName = "Editable.Preview";
EditableControl.displayName = "Editable.Control";
EditableEditTrigger.displayName = "Editable.EditTrigger";
EditableCancelTrigger.displayName = "Editable.CancelTrigger";
EditableSubmitTrigger.displayName = "Editable.SubmitTrigger";
// #endregion

import type { EditableRecipe } from "@pisagor/recipes/editable";
import { createContext } from "../../utils";

interface EditableContextValue {
  slots: EditableRecipe;
}

export const { EditableContext, useEditable } = createContext<EditableContextValue>()({
  name: "Editable",
});

import {
