  EditableSubmitTriggerProps,
} from "@ark-ui/react/editable";

export type {
  EditableInputProps,
  EditablePreviewProps,
  EditableProps,
  EditableRootProps,
} from "./editable";

export const Editable = Object.assign(EditableRoot, {
  Area: EditableArea,
