import { ark } from "@ark-ui/react/factory";
import { frameRecipe } from "@pisagor/recipes/frame";
import type { ComponentProps } from "react";
import { SurfaceContext } from "../surface/surface.context";
import { FrameContext, useFrame } from "./frame.context";

// #region Types
export type FrameHeaderProps = ComponentProps<typeof ark.header>;

export interface FrameRootProps extends ComponentProps<typeof ark.div> {
  /**
   * Style recipe. Defaults to `frameRecipe` from `@pisagor/recipes/frame`.
   *
   * @defaultValue frameRecipe
   */
  recipe?: typeof frameRecipe;
}

export type FramePanelProps = ComponentProps<typeof ark.div>;

export type FrameTitleProps = ComponentProps<typeof ark.div>;

export type FrameDescriptionProps = ComponentProps<typeof ark.div>;

export type FrameFooterProps = ComponentProps<typeof ark.footer>;
// #endregion

// #region Parts
export function FrameRoot({ children, recipe = frameRecipe, className, ...rest }: FrameRootProps) {
  const slots = recipe();

  return (
    <SurfaceContext value={{ depth: 0, variant: "secondary" }}>
      <FrameContext value={{ slots }}>
        <ark.div
          {...rest}
          className={slots.base({ className })}
          data-part="root"
          data-scope="frame"
        >
          {children}
        </ark.div>
      </FrameContext>
    </SurfaceContext>
  );
}

export function FramePanel({ children, className, ...rest }: FramePanelProps) {
  const { slots } = useFrame();

  return (
    <ark.div {...rest} className={slots.panel({ className })} data-part="panel" data-scope="frame">
      <SurfaceContext value={{ depth: 1, variant: "default" }}>{children}</SurfaceContext>
    </ark.div>
  );
}

export function FrameHeader({ children, className, ...rest }: FrameHeaderProps) {
  const { slots } = useFrame();

  return (
    <ark.header
      {...rest}
      className={slots.panelHeader({ className })}
      data-part="panel-header"
      data-scope="frame"
    >
      {children}
    </ark.header>
  );
}

export function FrameTitle({ children, className, ...rest }: FrameTitleProps) {
  const { slots } = useFrame();

  return (
    <ark.div
      {...rest}
      className={slots.panelTitle({ className })}
      data-part="panel-title"
      data-scope="frame"
    >
      {children}
    </ark.div>
  );
}

export function FrameDescription({ children, className, ...rest }: FrameDescriptionProps) {
  const { slots } = useFrame();

  return (
    <ark.div
      {...rest}
      className={slots.panelDescription({ className })}
      data-part="panel-description"
      data-scope="frame"
    >
      {children}
    </ark.div>
  );
}

export function FrameFooter({ children, className, ...rest }: FrameFooterProps) {
  const { slots } = useFrame();

  return (
    <ark.footer
      {...rest}
      className={slots.panelFooter({ className })}
      data-part="panel-footer"
      data-scope="frame"
    >
      {children}
    </ark.footer>
  );
}
// #endregion

// #region Display Names
FrameRoot.displayName = "Frame";
FramePanel.displayName = "Frame.Panel";
FrameHeader.displayName = "Frame.Header";
FrameTitle.displayName = "Frame.Title";
FrameDescription.displayName = "Frame.Description";
FrameFooter.displayName = "Frame.Footer";
// #endregion

import type { FrameRecipe } from "@pisagor/recipes/frame";
import { createContext } from "../../utils";

interface FrameContextValue {
  slots: FrameRecipe;
}

export const { FrameContext, useFrame } = createContext<FrameContextValue>()({
  name: "Frame",
});

import {
  FrameDescription,
  FrameFooter,
  FrameHeader,
  FramePanel,
  FrameRoot,
  FrameTitle,
} from "./frame";

export type {
  FrameDescriptionProps,
  FrameFooterProps,
  FrameHeaderProps,
  FramePanelProps,
  FrameRootProps,
  FrameTitleProps,
} from "./frame";

export const Frame = Object.assign(FrameRoot, {
  Description: FrameDescription,
  Footer: FrameFooter,
  Header: FrameHeader,
  Panel: FramePanel,
  Title: FrameTitle,
});

