interface JsonTreeViewContextValue {
  slots: JsonTreeViewRecipe;
}

export const { JsonTreeViewContext, useJsonTreeView } = createContext<JsonTreeViewContextValue>()({
  name: "JsonTreeView",
});

export type { JsonTreeViewTreeProps } from "@ark-ui/react/json-tree-view";

export type { JsonTreeViewProps } from "./json-tree-view";
export { JsonTreeView } from "./json-tree-view";

