                      <Listbox.ItemText>{item.label}</Listbox.ItemText>
                      <Listbox.ItemIndicator />
                    </Listbox.Item>
                  ))}
                </Listbox.ItemGroup>
              </Listbox.Content>
            </Listbox.Root>
          </Item>
        </Item.Group>
        <div className="flex flex-row-reverse justify-center gap-2 sm:flex-col">
          <Button
            aria-label="Move to selected"
            disabled={availableValue.length === 0}
            onClick={moveToSelected}
            size="icon-md"
            variant="outline"
          >
            <CaretRightIcon />
          </Button>
          <Button
            aria-label="Move to available"
            disabled={selectedValue.length === 0}
            onClick={moveToAvailable}
            size="icon-md"
            variant="outline"
          >
            <CaretLeftIcon />
          </Button>
        </div>
        <Item.Group variant="outline">
          <Item className="w-full p-1">
            <Listbox.Root
              className="min-h-40"
              collection={selectedCollection}
              onValueChange={(value) => setSelectedValue(Array.isArray(value) ? value : [value])}
