import type {
  QrCodeDownloadTriggerProps,
  QrCodeFrameProps,
  QrCodeOverlayProps,
  QrCodeRootProps as QrCodePrimitiveRootProps,
} from "@ark-ui/react/qr-code";
import { QrCode as QrCodePrimitive } from "@ark-ui/react/qr-code";
import { qrCodeRecipe } from "@pisagor/recipes/qr-code";

import { QrCodeContext, useQrCode } from "./qr-code.context";

// #region Types
export interface QrCodeRootProps extends QrCodePrimitiveRootProps {
  /**
   * Style recipe. Defaults to `qrCodeRecipe` from `@pisagor/recipes/qr-code`.
   *
   * @defaultValue qrCodeRecipe
   */
  recipe?: typeof qrCodeRecipe;
}

export type QrCodeDownloadProps = QrCodeDownloadTriggerProps;
// #endregion

// #region Parts
export function QrCodeRoot({
  children,
  recipe = qrCodeRecipe,
  className,
  ...rest
}: QrCodeRootProps) {
  const slots = recipe();

  return (
    <QrCodeContext value={{ slots }}>
      <QrCodePrimitive.Root {...rest} className={slots.base({ className })}>
        {children ?? <QrCodeFrame />}
      </QrCodePrimitive.Root>
    </QrCodeContext>
  );
}

export function QrCodeFrame({ className, ...rest }: QrCodeFrameProps) {
  const { slots } = useQrCode();

  return (
    <QrCodePrimitive.Frame {...rest} className={slots.frame({ className })}>
      <QrCodePrimitive.Pattern className={slots.pattern()} />
    </QrCodePrimitive.Frame>
  );
}

export function QrCodeOverlay({ className, ...rest }: QrCodeOverlayProps) {
  const { slots } = useQrCode();

  return <QrCodePrimitive.Overlay {...rest} className={slots.overlay({ className })} />;
}

export function QrCodeDownload(props: QrCodeDownloadProps) {
  return <QrCodePrimitive.DownloadTrigger {...props} />;
}
// #endregion

// #region Display Names
QrCodeRoot.displayName = "QrCode";
QrCodeFrame.displayName = "QrCode.Frame";
QrCodeOverlay.displayName = "QrCode.Overlay";
QrCodeDownload.displayName = "QrCode.Download";
// #endregion

import type { QrCodeRecipe } from "@pisagor/recipes/qr-code";
import { createContext } from "../../utils";

interface QrCodeContextValue {
  slots: QrCodeRecipe;
}

export const { QrCodeContext, useQrCode } = createContext<QrCodeContextValue>()({
  name: "QrCode",
});

import { QrCodeDownload, QrCodeFrame, QrCodeOverlay, QrCodeRoot } from "./qr-code";

export type {
  QrCodeDownloadTriggerProps,
  QrCodeFrameProps,
  QrCodeOverlayProps,
  QrCodeRootProps,
} from "@ark-ui/react/qr-code";

export type { QrCodeDownloadProps } from "./qr-code";

export const QrCode = Object.assign(QrCodeRoot, {
  Download: QrCodeDownload,
  Frame: QrCodeFrame,
  Overlay: QrCodeOverlay,
});

