      >
        <Resizable.Panel className={panelClassName()} id="1">
          One
        </Resizable.Panel>
        <Resizable.ResizeTrigger id="1:2" withHandle />

        <Resizable.Panel className="min-h-0 h-full min-w-0" id="2">
          <Resizable
            className="size-full"
            defaultSize={[50, 50]}
            orientation="vertical"
            panels={[
