export const OrientationVertical = meta.story({
  render: () => (
    <ResizableFrame heightClassName="h-112">
      <Resizable
        className="size-full rounded-md border"
        defaultSize={[50, 50]}
        orientation="vertical"
        panels={[{ id: "1" }, { id: "2" }]}
      >
        <Resizable.Panel className={panelClassName("vertical")} id="1">
          Top
        </Resizable.Panel>
