          <Select.ItemGroup heading="Fruits">
            {collection.items.map((item) => (
              <Select.Item item={item} key={item}>
                {item}
              </Select.Item>
            ))}
          </Select.ItemGroup>
        </Select.Content>
      </Select.Root>
    );
  },
});

