import { ark } from "@ark-ui/react/factory";
import { separatorRecipe } from "@pisagor/recipes/separator";
import type { ComponentProps } from "react";

// #region Types
export interface SeparatorProps extends ComponentProps<typeof ark.div> {
  /**
