import { ark } from "@ark-ui/react/factory";
import type {
  TimerActionTriggerProps,
  TimerAreaProps,
  TimerControlProps,
  TimerItemProps,
  TimerRootProps as TimerPrimitiveRootProps,
  TimerSeparatorProps,
} from "@ark-ui/react/timer";
import { Timer as TimerPrimitive, useTimerContext } from "@ark-ui/react/timer";
import { timerItemGroupRecipe, timerRecipe } from "@pisagor/recipes/timer";
import type { ComponentProps } from "react";
import { Fragment } from "react";
import { TimerContext, TimerItemGroupContext, useTimer, useTimerItemGroup } from "./timer.context";

// #region Types
type TimerUnit = "hours" | "minutes" | "seconds";

export interface TimerItemGroupProps extends ComponentProps<typeof ark.div> {
  /**
   * The orientation of the timer item group.
   *
   * @defaultValue "vertical"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Style recipe. Defaults to `timerItemGroupRecipe` from `@pisagor/recipes/timer`.
   *
   * @defaultValue timerItemGroupRecipe
   */
  itemGroupRecipe?: typeof timerItemGroupRecipe;
}

export interface TimerActionProps extends Omit<TimerActionTriggerProps, "action"> {}

export interface TimerRootProps extends TimerPrimitiveRootProps {
  units?: TimerUnit[];
  /** Auto-render Timer.Control with play and reset buttons */
  isControlsVisible?: boolean;
  /**
   * Style recipe. Defaults to `timerRecipe` from `@pisagor/recipes/timer`.
   *
   * @defaultValue timerRecipe
   */
  recipe?: typeof timerRecipe;
}

export type TimerItemLabelProps = ComponentProps<typeof ark.div>;
// #endregion

// #region Parts
export function TimerRoot({
  isControlsVisible,
  children,
  units,
  recipe = timerRecipe,
  className,
  ...rest
}: TimerRootProps) {
  const slots = recipe();

  return (
    <TimerContext value={{ slots }}>
      <TimerPrimitive.Root {...rest} className={slots.base({ className })}>
        {units && (
          <TimerArea>
            {units.map((unit, index) => (
              <Fragment key={unit}>
                {index > 0 && <TimerSeparator />}
                <TimerItemGroup>
                  <TimerItem type={unit} />
                  <TimerItemLabel>{unit}</TimerItemLabel>
                </TimerItemGroup>
              </Fragment>
            ))}
          </TimerArea>
        )}
        {isControlsVisible && (
          <TimerControl>
            <TimerPlay />
            <TimerReset />
          </TimerControl>
        )}
        {children}
      </TimerPrimitive.Root>
    </TimerContext>
  );
}

export function TimerArea({ className, ...rest }: TimerAreaProps) {
  const { slots } = useTimer();

  return <TimerPrimitive.Area {...rest} className={slots.area({ className })} />;
}

export function TimerItemGroup({
  orientation = "vertical",
  children,
  itemGroupRecipe = timerItemGroupRecipe,
  className,
  ...rest
}: TimerItemGroupProps) {
  const slots = itemGroupRecipe();

  return (
    <TimerItemGroupContext value={{ slots }}>
      <ark.div
        {...rest}
        className={slots.base({ className })}
        data-orientation={orientation}
        data-part="item-group"
        data-scope="timer"
      >
        {children}
      </ark.div>
    </TimerItemGroupContext>
  );
}

export function TimerItem({ className, ...rest }: TimerItemProps) {
  const { slots } = useTimerItemGroup();

  return <TimerPrimitive.Item {...rest} className={slots.item({ className })} />;
}

export function TimerItemLabel({ className, ...rest }: TimerItemLabelProps) {
  const { slots } = useTimerItemGroup();

  return (
    <ark.div
      {...rest}
      className={slots.label({ className })}
      data-part="item-label"
      data-scope="timer"
    />
  );
}

export function TimerSeparator({ children, className, ...rest }: TimerSeparatorProps) {
  const { slots } = useTimer();

  return (
    <TimerPrimitive.Separator {...rest} className={slots.separator({ className })}>
      {children ?? ":"}
    </TimerPrimitive.Separator>
  );
}

export function TimerControl({ className, ...rest }: TimerControlProps) {
  const { slots } = useTimer();

  return <TimerPrimitive.Control {...rest} className={slots.control({ className })} />;
}

export function TimerActionTrigger(props: TimerActionTriggerProps) {
  return <TimerPrimitive.ActionTrigger {...props} />;
}

export function TimerPause(props: TimerActionProps) {
  return <TimerPrimitive.ActionTrigger {...props} action="pause" aria-label="Pause" />;
}

export function TimerResume(props: TimerActionProps) {
  return <TimerPrimitive.ActionTrigger {...props} action="resume" aria-label="Resume" />;
}

export function TimerStart(props: TimerActionProps) {
  return <TimerPrimitive.ActionTrigger {...props} action="start" aria-label="Start" />;
}

export function TimerReset(props: TimerActionProps) {
  return <TimerPrimitive.ActionTrigger {...props} action="reset" aria-label="Reset" />;
}

export function TimerRestart(props: TimerActionProps) {
  return <TimerPrimitive.ActionTrigger {...props} action="restart" aria-label="Restart" />;
}

export function TimerPlay(props: TimerActionProps) {
  const { paused } = useTimerContext();

  if (paused) {
    return <TimerResume {...props} />;
  }

  return <TimerStart {...props} />;
}
// #endregion

// #region Display Names
TimerRoot.displayName = "Timer";
TimerArea.displayName = "Timer.Area";
TimerItemGroup.displayName = "Timer.ItemGroup";
TimerItem.displayName = "Timer.Item";
TimerItemLabel.displayName = "Timer.ItemLabel";
TimerSeparator.displayName = "Timer.Separator";
TimerControl.displayName = "Timer.Control";
TimerActionTrigger.displayName = "Timer.ActionTrigger";
TimerPause.displayName = "Timer.Pause";
TimerResume.displayName = "Timer.Resume";
TimerStart.displayName = "Timer.Start";
TimerReset.displayName = "Timer.Reset";
TimerRestart.displayName = "Timer.Restart";
TimerPlay.displayName = "Timer.Play";
// #endregion

import type { TimerItemGroupRecipe, TimerRecipe } from "@pisagor/recipes/timer";
import { createContext } from "../../utils";

interface TimerContextValue {
  slots: TimerRecipe;
}

interface TimerItemGroupContextValue {
  slots: TimerItemGroupRecipe;
}

export const { TimerContext, useTimer } = createContext<TimerContextValue>()({
  name: "Timer",
});

export const { TimerItemGroupContext, useTimerItemGroup } =
  createContext<TimerItemGroupContextValue>()({
    name: "TimerItemGroup",
  });

import { Portal } from "@ark-ui/react/portal";
import type {
  CreateToasterReturn,
  ToastActionTriggerProps,
  ToastCloseTriggerProps,
  ToastDescriptionProps,
  ToasterProps as ToasterPrimitiveProps,
  ToastRootProps,
  ToastTitleProps,
} from "@ark-ui/react/toast";
import {
  createToaster,
  Toaster as ToasterPrimitive,
  Toast as ToastPrimitive,
} from "@ark-ui/react/toast";
import {
  CheckCircleIcon,
  InfoIcon,
  WarningCircleIcon,
  WarningIcon,
  XIcon,
} from "@phosphor-icons/react";
import { type ToastItemRecipeSlot, toastItemRecipe, toastRecipe } from "@pisagor/recipes/toast";
import type { ComponentProps, CSSProperties, ReactNode } from "react";
import type { VariantClassNames } from "../../internal/types";
import { Button } from "../button";
import { Spinner } from "../spinner";
import { ToastItemContext, useToastItem } from "./toast.context";

// #region Types
type ToastItemClassNames = VariantClassNames<ToastItemRecipeSlot>;

export interface ToasterRootProps extends Omit<ToasterPrimitiveProps, "toaster" | "children"> {
  /**
   * Style recipe. Defaults to `toastRecipe` from `@pisagor/recipes/toast`.
   *
   * @defaultValue toastRecipe
   */
  recipe?: typeof toastRecipe;
}

export interface ToasterProps extends ToasterRootProps {
  /** Toaster instance */
  toaster?: CreateToasterReturn<ReactNode>;
}

export interface ToastItemRootProps extends ToastRootProps {
  /**
   * Style recipe. Defaults to `toastItemRecipe` from `@pisagor/recipes/toast`.
   *
   * @defaultValue toastItemRecipe
   */
  itemRecipe?: typeof toastItemRecipe;
}

export interface ToastItemProps extends ToastItemRootProps {
  /** Slot class names */
  classNames?: ToastItemClassNames;
  /** Extra props forwarded to the toast actions container element */
  actionsProps?: Omit<ComponentProps<"div">, "className">;
  /** Extra props forwarded to the toast action trigger element */
  actionTriggerProps?: Omit<
    ToastActionTriggerProps,
    "asChild" | "children" | "className" | "onClick"
  >;
  /** Extra props forwarded to the toast close trigger element */
  closeTriggerProps?: Omit<ToastCloseTriggerProps, "asChild" | "children" | "className">;
  /** Extra props forwarded to the toast description element */
  descriptionProps?: Omit<ToastDescriptionProps, "children" | "className">;
  /** Extra props forwarded to the toast icon wrapper element */
  iconProps?: Omit<ComponentProps<"div">, "className">;
  /** Extra props forwarded to the toast title element */
  titleProps?: Omit<ToastTitleProps, "children" | "className">;
  /** The toast item data */
  toast: ToastPrimitive.Options;
}
// #endregion

// #region Parts
export const toast = createToaster({
  max: 3,
  overlap: true,
  placement: "bottom-end",
});

export function ToasterRoot({
  toaster: toasterInstance = toast,
  recipe = toastRecipe,
  className,
  style,
  ...rest
}: ToasterProps) {
  return (
    <Portal>
      <ToasterPrimitive
        {...rest}
        className={recipe({ className })}
        style={{ "--width": "356px", ...style } as CSSProperties}
        toaster={toasterInstance}
      >
        {(toastItem) => <ToastItem toast={toastItem} />}
      </ToasterPrimitive>
    </Portal>
  );
}

const TOAST_ICONS = {
  error: <WarningCircleIcon />,
  info: <InfoIcon />,
  loading: <Spinner />,
  success: <CheckCircleIcon />,
  warning: <WarningIcon />,
} as const;

function ToastItemRoot({
  children,
  itemRecipe = toastItemRecipe,
  className,
  ...rest
}: ToastItemRootProps) {
  const slots = itemRecipe();

  return (
    <ToastItemContext value={{ slots }}>
      <ToastPrimitive.Root {...rest} className={slots.base({ className })}>
        {children}
      </ToastPrimitive.Root>
    </ToastItemContext>
  );
}

function ToastItemContent({
  actionsProps,
  actionTriggerProps,
  closeTriggerProps,
  descriptionProps,
  iconProps,
  titleProps,
  toast: toastData,
  classNames,
}: Omit<ToastItemProps, keyof ToastItemRootProps> & Pick<ToastItemProps, "toast">) {
  const { slots } = useToastItem();
  const ToastIcon = toastData.type ? TOAST_ICONS[toastData.type as keyof typeof TOAST_ICONS] : null;
  const isExplicitClosable = toastData.closable === false;

  return (
    <>
      <div className={slots.content({ className: classNames?.content })}>
        <div
          {...iconProps}
          className={slots.icon({ className: classNames?.icon })}
          data-part="icon"
          data-scope="toast"
        >
          {ToastIcon}
        </div>

        <div className={slots.body({ className: classNames?.body })}>
          <ToastPrimitive.Title
            {...titleProps}
            className={slots.title({ className: classNames?.title })}
          >
            {toastData.title}
          </ToastPrimitive.Title>

          {toastData.description && (
            <ToastPrimitive.Description
              {...descriptionProps}
              className={slots.description({ className: classNames?.description })}
            >
              {toastData.description}
            </ToastPrimitive.Description>
          )}
        </div>
      </div>

      <div {...actionsProps} className={slots.actions({ className: classNames?.actions })}>
        {toastData.action && (
          <ToastPrimitive.ActionTrigger
            {...actionTriggerProps}
            asChild
            onClick={toastData.action.onClick}
          >
            <Button size="sm" variant="secondary">
              {toastData.action.label}
            </Button>
          </ToastPrimitive.ActionTrigger>
        )}

        {!isExplicitClosable && (
          <ToastPrimitive.CloseTrigger {...closeTriggerProps} asChild>
            <Button
              aria-label="Close"
              className={slots.close({ className: classNames?.close })}
              size="icon-xs"
              variant="ghost"
            >
              <XIcon />
            </Button>
          </ToastPrimitive.CloseTrigger>
        )}
      </div>
    </>
  );
}

export function ToastItem({
  actionsProps,
  actionTriggerProps,
  closeTriggerProps,
  descriptionProps,
  iconProps,
  titleProps,
  toast: toastData,
  className,
  classNames,
  ...rest
}: ToastItemProps) {
  return (
    <ToastItemRoot {...rest} className={className}>
      <ToastItemContent
        actionsProps={actionsProps}
        actionTriggerProps={actionTriggerProps}
        classNames={classNames}
        closeTriggerProps={closeTriggerProps}
        descriptionProps={descriptionProps}
        iconProps={iconProps}
        titleProps={titleProps}
        toast={toastData}
      />
    </ToastItemRoot>
  );
}
// #endregion

// #region Display Names
ToasterRoot.displayName = "Toaster";
ToastItem.displayName = "Toaster.Item";
// #endregion

import type { ToastItemRecipe } from "@pisagor/recipes/toast";
import { createContext } from "../../utils";

interface ToastItemContextValue {
  slots: ToastItemRecipe;
}

export const { ToastItemContext, useToastItem } = createContext<ToastItemContextValue>()({
  name: "ToastItem",
});

import { ToasterRoot, ToastItem, toast } from "./toast";

export type {
  ToastActionTriggerProps,
  ToastCloseTriggerProps,
  ToastDescriptionProps,
  ToastTitleProps,
} from "@ark-ui/react/toast";

export type {
  ToasterProps,
  ToasterRootProps,
  ToastItemProps,
  ToastItemRootProps,
} from "./toast";
export { toast };

export const Toaster = Object.assign(ToasterRoot, {
  Item: ToastItem,
});

