        title: "Final step",
        type: "tooltip",
      },
    ];
    const [logs, setLogs] = useState<{ id: number; message: string }[]>([]);
    const nextLogId = useRef(0);

    const addLog = (message: string) => {
      nextLogId.current += 1;
      setLogs((prev) => [...prev, { id: nextLogId.current, message }]);
    };

    return (
      <div className="flex flex-col gap-2">
        <Tour
