import {
  ArrowSquareOutIcon,
  FileCodeIcon,
  FileJsIcon,
  FilePlusIcon,
  FileTextIcon,
  FolderPlusIcon,
  LinkIcon,
  PackageIcon,
  PencilSimpleIcon,
  StarIcon,
  TrashIcon,
} from "@phosphor-icons/react";
import type { NodeProviderProps, TreeNodeType } from "@pisagor/react";
import { ContextMenu, createFileIcons, createTreeCollection, TreeView } from "@pisagor/react";
import { useState } from "react";
import preview from "#/storybook/preview";

const meta = preview.meta({
  component: TreeView,
  parameters: {
    docs: {
      description: {
        component:
          "Browses nested folders or categories in an expandable tree for files, navigation, and hierarchies.",
      },
    },
    metadata: {
      aliases: ["tree"],
      api: "compound",
      taxonomy: "pattern",
    },
  },
  subcomponents: {
    Branch: TreeView.Branch,
    BranchContent: TreeView.BranchContent,
    BranchControl: TreeView.BranchControl,
    BranchIndicator: TreeView.BranchIndicator,
    Item: TreeView.Item,
    ItemText: TreeView.ItemText,
    Label: TreeView.Label,
    NodeCheckbox: TreeView.NodeCheckbox,
    NodeProvider: TreeView.NodeProvider,
    Tree: TreeView.Tree,
  },
  title: "Components/Navigation/Tree View",
});

export const Default = meta.story({
  render: () => {
    const collection = createTreeCollection({
      rootNode: {
        children: [
          {
            children: [
              { id: "app/page.tsx", name: "page.tsx" },
              { id: "app/layout.tsx", name: "layout.tsx" },
            ],
            id: "app",
            name: "app",
          },
          {
            children: [
              { id: "components/button.tsx", name: "button.tsx" },
              { id: "components/input.tsx", name: "input.tsx" },
            ],
            id: "components",
            name: "components",
          },
          { id: "package.json", name: "package.json" },
          { id: "readme.md", name: "README.md" },
        ],
        id: "ROOT",
        name: "",
      },
    });

    const TreeNode = ({ indexPath, node, ...rest }: NodeProviderProps) => {
      return (
        <TreeView.NodeProvider {...rest} indexPath={indexPath} node={node}>
          {node.children ? (
            <TreeView.Branch>
              <TreeView.BranchControl>{node.name}</TreeView.BranchControl>

              <TreeView.BranchContent>
                {node.children.map((child, index) => (
                  <TreeNode indexPath={[...indexPath, index]} key={child.id} node={child} />
                ))}
              </TreeView.BranchContent>
            </TreeView.Branch>
          ) : (
            <TreeView.Item>
              <TreeView.ItemText>{node.name}</TreeView.ItemText>
            </TreeView.Item>
          )}
        </TreeView.NodeProvider>
      );
    };
    return (
      <div>
        <TreeView collection={collection}>
          <TreeView.Tree>
            {collection.rootNode.children?.map((node, index) => (
              <TreeNode indexPath={[index]} key={node.id} node={node} />
            ))}
          </TreeView.Tree>
        </TreeView>
      </div>
    );
  },
});

export const Links = meta.story({
  render: () => {
    interface TreeNodeWithLinks extends TreeNodeType<unknown> {
      href?: string;
    }
    const collection = createTreeCollection({
      rootNode: {
        children: [
          {
            children: [
              {
                href: "/docs",
                id: "docs/introduction",
